/* --- Color Palette Variables --- */
:root {
  --deloitte-green: #86BC25;
  --cool-black: #0F0B0B;
  --pure-white: #FFFFFF;
  --cool-gray: #75787B;
  --light-gray: #D0D0CE;
  --light-bg: #FBFBFB;
  --deloitte-blue: #00A3E0;
  --dark-teal: #004F59;
}

/* --- Base Styles --- */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--cool-black);
  background-color: var(--pure-white);
  line-height: 1.6;
  overflow-x: hidden;
}

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 48px;
}

/* --- Typography --- */
h1, h2, h3 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--cool-black);
}

h2 {
  font-size: 36px;
  margin-bottom: 16px;
}

p {
  color: var(--cool-gray);
  font-size: 18px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 24px;
  border-radius: 4px;
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s ease;
  cursor: pointer;
  border: 1px solid transparent;
}

.btn-primary {
  background-color: var(--deloitte-green);
  color: var(--pure-white);
}

.btn-primary:hover {
  background-color: #72a31f;
  box-shadow: 0 4px 12px rgba(134, 188, 37, 0.3);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--light-gray);
  color: var(--cool-black);
}

.btn-outline:hover {
  border-color: var(--cool-gray);
  background-color: var(--light-bg);
}

.btn-text {
  background-color: transparent;
  color: var(--cool-black);
}

.btn-text:hover {
  color: var(--deloitte-green);
}

.btn-large {
  padding: 14px 32px;
  font-size: 16px;
}

/* --- Navigation --- */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 80px;
  background-color: var(--pure-white);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 48px;
  z-index: 1000;
  border-bottom: 1px solid transparent;
  transition: all 0.3s ease;
}

.navbar.scrolled {
  border-bottom: 1px solid var(--light-gray);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.03);
}

.logo-container {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-dot {
  width: 14px;
  height: 14px;
  background-color: var(--deloitte-green);
  border-radius: 50%;
}

.brand-text {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.nav-links {
  display: flex;
  list-style: none;
  gap: 40px;
}

.nav-links a {
  text-decoration: none;
  color: var(--cool-gray);
  font-weight: 500;
  font-size: 15px;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--cool-black);
}

.nav-actions {
  display: flex;
  gap: 16px;
  align-items: center;
}

/* --- Hero Section --- */
.hero {
  padding-top: 160px;
  padding-bottom: 100px;
  background: linear-gradient(135deg, var(--pure-white) 0%, var(--light-bg) 100%);
  position: relative;
  overflow: hidden;
}

.hero-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.hero-label {
  display: inline-block;
  padding: 6px 14px;
  background-color: rgba(0, 163, 224, 0.1);
  color: var(--deloitte-blue);
  font-size: 13px;
  font-weight: 700;
  border-radius: 20px;
  margin-bottom: 24px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.hero-title {
  font-size: 56px;
  letter-spacing: -1px;
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 20px;
  margin-bottom: 40px;
  max-width: 90%;
}

.hero-cta {
  display: flex;
  gap: 16px;
}

/* Hero CSS Mockup */
.mockup-window {
  background-color: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 8px;
  box-shadow: 0 24px 48px rgba(15, 11, 11, 0.08);
  display: flex;
  flex-direction: column;
  height: 400px;
  overflow: hidden;
  position: relative;
}

.mockup-header {
  height: 40px;
  border-bottom: 1px solid var(--light-gray);
  display: flex;
  align-items: center;
  padding: 0 16px;
  background-color: var(--light-bg);
}

.mockup-dots {
  display: flex;
  gap: 6px;
}

.mockup-dots span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--light-gray);
}

.mockup-sidebar {
  position: absolute;
  top: 40px;
  left: 0;
  bottom: 0;
  width: 60px;
  border-right: 1px solid var(--light-gray);
  padding: 16px 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  background-color: var(--pure-white);
}

.sidebar-item {
  width: 24px;
  height: 24px;
  background-color: var(--light-gray);
  border-radius: 4px;
  opacity: 0.5;
}

.sidebar-item.active {
  background-color: var(--deloitte-green);
  opacity: 1;
}

.mockup-body {
  margin-left: 60px;
  padding: 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 24px;
  background-color: #FAFAFA;
}

.mockup-card-row {
  display: flex;
  gap: 16px;
}

.mockup-card {
  flex: 1;
  height: 80px;
  background-color: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 6px;
}

.mockup-chart {
  flex: 1;
  background-color: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 6px;
  display: flex;
  align-items: flex-end;
  padding: 24px;
  gap: 16px;
}

.bar {
  flex: 1;
  background-color: var(--light-gray);
  border-radius: 4px 4px 0 0;
  opacity: 0.6;
}

.bar.accent {
  background-color: var(--deloitte-blue);
  opacity: 1;
}

/* --- Metrics Section --- */
.metrics {
  background-color: var(--dark-teal);
  padding: 60px 0;
  color: var(--pure-white);
}

.metrics-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.metric-item {
  text-align: center;
  flex: 1;
}

.metric-word {
  font-size: 40px;
  font-weight: 800;
  color: var(--pure-white);
  line-height: 1;
  margin-bottom: 12px;
  display: flex;
  justify-content: center;
  align-items: center;
  letter-spacing: -0.5px;
}

.metric-text {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.8);
  font-weight: 500;
}

.metric-divider {
  width: 1px;
  height: 60px;
  background-color: rgba(255, 255, 255, 0.2);
}

/* --- Features / How It Works --- */
.features {
  padding: 120px 0;
  background-color: var(--pure-white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 80px;
}

.feature-row {
  display: flex;
  align-items: center;
  gap: 80px;
  margin-bottom: 120px;
}

.feature-row:last-child {
  margin-bottom: 0;
}

.feature-row.reverse {
  flex-direction: row-reverse;
}

.feature-text {
  flex: 1;
}

.step-number {
  font-size: 18px;
  font-weight: 700;
  color: var(--light-gray);
  margin-bottom: 16px;
  font-family: monospace;
}

.feature-text h3 {
  font-size: 32px;
  margin-bottom: 20px;
}

.feature-text p {
  font-size: 18px;
}

.feature-visual {
  flex: 1;
}

.visual-placeholder {
  width: 100%;
  height: 350px;
  background-color: var(--light-bg);
  border: 1px solid var(--light-gray);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}

.visual-placeholder.blue-accent {
  border-top: 4px solid var(--deloitte-blue);
}

.visual-placeholder.green-accent {
  border-top: 4px solid var(--deloitte-green);
}

.visual-placeholder.teal-accent {
  border-top: 4px solid var(--dark-teal);
}

.data-flow {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 200px;
  height: 100px;
  border: 2px dashed var(--light-gray);
  border-radius: 8px;
}

.data-flow::before {
  content: "";
  position: absolute;
  left: -60px;
  top: 45%;
  width: 40px;
  height: 10px;
  background: var(--deloitte-blue);
  border-radius: 4px;
}

.data-flow::after {
  content: "";
  position: absolute;
  right: -60px;
  top: 45%;
  width: 40px;
  height: 10px;
  background: var(--cool-black);
  border-radius: 4px;
}

.anomaly-chart {
  position: absolute;
  inset: 40px;
  border-left: 2px solid var(--light-gray);
  border-bottom: 2px solid var(--light-gray);
}

.point {
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  transform: translate(-50%, 50%);
}

.point.normal {
  background-color: var(--cool-gray);
}

.point.alert {
  background-color: #E24C4B;
  box-shadow: 0 0 0 6px rgba(226, 76, 75, 0.2);
}

.report-lines {
  position: absolute;
  inset: 40px 60px;
  background: var(--pure-white);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.line {
  height: 12px;
  background-color: var(--light-gray);
  border-radius: 4px;
}

.line.title {
  width: 40%;
  height: 20px;
  background-color: var(--dark-teal);
  margin-bottom: 10px;
}

.line.full {
  width: 100%;
}

.line.half {
  width: 60%;
}

/* --- NEW: Platform Guide Section --- */
.platform-guide {
  padding: 100px 0;
  background-color: var(--light-bg);
  border-top: 1px solid var(--light-gray);
}

.guide-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.guide-card {
  background-color: var(--pure-white);
  padding: 40px 32px;
  border-radius: 8px;
  border: 1px solid var(--light-gray);
  transition: all 0.3s ease;
  position: relative;
}

.guide-card:hover {
  border-color: var(--deloitte-blue);
  transform: translateY(-5px);
  box-shadow: 0 12px 24px rgba(15, 11, 11, 0.04);
}

.guide-icon {
  font-size: 40px;
  margin-bottom: 24px;
}

.guide-card h3 {
  font-size: 22px;
  margin-bottom: 16px;
}

.guide-card p {
  font-size: 16px;
}

/* --- NEW: Tooltips & Highlights --- */
.highlight-word {
  border-bottom: 2px dashed var(--deloitte-green);
  cursor: help;
  transition: all 0.2s;
  display: inline-block;
}

.highlight-word:hover {
  color: var(--pure-white) !important;
  background-color: var(--deloitte-green);
}

.tooltip-wrapper {
  position: relative;
  cursor: help;
}

.tooltip-wrapper-inline {
  position: relative;
  cursor: help;
  display: inline-block;
}

/* The actual tooltip box */
.tooltip-wrapper::after,
.tooltip-wrapper-inline::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  width: 250px;
  background-color: var(--cool-black);
  color: var(--pure-white);
  text-align: center;
  padding: 12px 16px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 100;
  pointer-events: none;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.15);
}

/* Arrow for tooltip */
.tooltip-wrapper::before,
.tooltip-wrapper-inline::before {
  content: "";
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  border: 6px solid transparent;
  border-top-color: var(--cool-black);
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 100;
  pointer-events: none;
}

.tooltip-wrapper:hover::after,
.tooltip-wrapper:hover::before,
.tooltip-wrapper-inline:hover::after,
.tooltip-wrapper-inline:hover::before {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(-10px);
}

/* --- Use Cases --- */
.use-cases {
  padding: 100px 0;
  background-color: var(--pure-white);
  border-top: 1px solid var(--light-gray);
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 60px;
}

.use-case-card {
  background-color: var(--light-bg);
  padding: 48px 32px;
  border-radius: 8px;
  border: 1px solid var(--light-gray);
  transition: all 0.3s ease;
}

.use-case-card:hover {
  border-color: var(--deloitte-blue);
  transform: translateY(-5px);
  box-shadow: 0 12px 24px rgba(15, 11, 11, 0.04);
}

.card-icon {
  width: 48px;
  height: 48px;
  color: var(--dark-teal);
  margin-bottom: 24px;
}

.use-case-card h3 {
  font-size: 22px;
  margin-bottom: 16px;
}

.use-case-card p {
  font-size: 16px;
}

/* --- Final CTA --- */
.final-cta {
  background-color: var(--dark-teal);
  padding: 100px 0;
  color: var(--pure-white);
}

.final-cta h2 {
