/* --- Color Palette Variables --- */
:root {
  --deloitte-green: #86BC25;
  --cool-black: #0F0B0B;
  --pure-white: #FFFFFF;
  --cool-gray: #75787B;
  --light-gray: #D0D0CE;
  --light-bg: #FBFBFB;
  --deloitte-blue: #00A3E0;
  --dark-teal: #004F59;
}

/* --- Base Styles --- */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--cool-black);
  background-color: var(--pure-white);
  line-height: 1.6;
  overflow-x: hidden;
}

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 48px;
}

/* --- Typography --- */
h1, h2, h3 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--cool-black);
}

h2 {
  font-size: 36px;
  margin-bottom: 16px;
}

p {
  color: var(--cool-gray);
  font-size: 18px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 24px;
  border-radius: 4px;
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s ease;
  cursor: pointer;
  border: 1px solid transparent;
}

.btn-primary {
  background-color: var(--deloitte-green);
  color: var(--pure-white);
}

.btn-primary:hover {
  background-color: #72a31f;
  box-shadow: 0 4px 12px rgba(134, 188, 37, 0.3);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--light-gray);
  color: var(--cool-black);
}

.btn-outline:hover {
  border-color: var(--cool-gray);
  background-color: var(--light-bg);
}

.btn-text {
  background-color: transparent;
  color: var(--cool-black);
}

.btn-text:hover {
  color: var(--deloitte-green);
}

.btn-large {
  padding: 14px 32px;
  font-size: 16px;
}

/* --- Navigation --- */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 80px;
  background-color: var(--pure-white);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 48px;
  z-index: 1000;
  border-bottom: 1px solid transparent;
  transition: all 0.3s ease;
}

.navbar.scrolled {
  border-bottom: 1px solid var(--light-gray);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.03);
}

.logo-container {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-dot {
  width: 14px;
  height: 14px;
  background-color: var(--deloitte-green);
  border-radius: 50%;
}

.brand-text {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.nav-links {
  display: flex;
  list-style: none;
  gap: 40px;
}

.nav-links a {
  text-decoration: none;
  color: var(--cool-gray);
  font-weight: 500;
  font-size: 15px;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--cool-black);
}

.nav-actions {
  display: flex;
  gap: 16px;
  align-items: center;
}

/* --- Hero Section --- */
.hero {
  padding-top: 160px;
  padding-bottom: 100px;
  background: linear-gradient(135deg, var(--pure-white) 0%, var(--light-bg) 100%);
  position: relative;
  overflow: hidden;
}

.hero-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.hero-label {
  display: inline-block;
  padding: 6px 14px;
  background-color: rgba(0, 163, 224, 0.1);
  color: var(--deloitte-blue);
  font-size: 13px;
  font-weight: 700;
  border-radius: 20px;
  margin-bottom: 24px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.hero-title {
  font-size: 56px;
  letter-spacing: -1px;
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 20px;
  margin-bottom: 40px;
  max-width: 90%;
}

.hero-cta {
  display: flex;
  gap: 16px;
}

/* Hero CSS Mockup */
.mockup-window {
  background-color: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 8px;
  box-shadow: 0 24px 48px rgba(15, 11, 11, 0.08);
  display: flex;
  flex-direction: column;
  height: 400px;
  overflow: hidden;
  position: relative;
}

.mockup-header {
  height: 40px;
  border-bottom: 1px solid var(--light-gray);
