}

.mockup-dots {
  display: flex;
  gap: 6px;
}

.mockup-dots span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--light-gray);
}

.mockup-sidebar {
  position: absolute;
  top: 40px;
  left: 0;
  bottom: 0;
  width: 60px;
  border-right: 1px solid var(--light-gray);
  padding: 16px 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  background-color: var(--pure-white);
}

.sidebar-item {
  width: 24px;
  height: 24px;
  background-color: var(--light-gray);
  border-radius: 4px;
  opacity: 0.5;
}

.sidebar-item.active {
  background-color: var(--deloitte-green);
  opacity: 1;
}

.mockup-body {
  margin-left: 60px;
  padding: 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 24px;
  background-color: #FAFAFA;
}

.mockup-card-row {
  display: flex;
  gap: 16px;
}

.mockup-card {
  flex: 1;
  height: 80px;
  background-color: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 6px;
}

.mockup-chart {
  flex: 1;
  background-color: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 6px;
  display: flex;
  align-items: flex-end;
  padding: 24px;
  gap: 16px;
}

.bar {
  flex: 1;
  background-color: var(--light-gray);
  border-radius: 4px 4px 0 0;
  opacity: 0.6;
}

.bar.accent {
  background-color: var(--deloitte-blue);
  opacity: 1;
}

/* --- Metrics Section --- */
.metrics {
  background-color: var(--dark-teal);
  padding: 60px 0;
  color: var(--pure-white);
}

.metrics-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.metric-item {
  text-align: center;
  flex: 1;
}

.metric-word {
  font-size: 40px;
  font-weight: 800;
  color: var(--pure-white);
  line-height: 1;
  margin-bottom: 12px;
  display: flex;
  justify-content: center;
  align-items: center;
  letter-spacing: -0.5px;
}

.metric-text {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.8);
  font-weight: 500;
}

.metric-divider {
  width: 1px;
  height: 60px;
  background-color: rgba(255, 255, 255, 0.2);
}

/* --- Features / How It Works --- */
.features {
  padding: 120px 0;
  background-color: var(--pure-white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 80px;
}

.feature-row {
  display: flex;
  align-items: center;
  gap: 80px;
  margin-bottom: 120px;
}

.feature-row:last-child {
  margin-bottom: 0;
}

.feature-row.reverse {
