}

.feature-text {
  flex: 1;
}

.step-number {
  font-size: 18px;
  font-weight: 700;
  color: var(--light-gray);
  margin-bottom: 16px;
  font-family: monospace;
}

.feature-text h3 {
  font-size: 32px;
  margin-bottom: 20px;
}

.feature-text p {
  font-size: 18px;
}

.feature-visual {
  flex: 1;
}

.visual-placeholder {
  width: 100%;
  height: 350px;
  background-color: var(--light-bg);
  border: 1px solid var(--light-gray);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}

.visual-placeholder.blue-accent {
  border-top: 4px solid var(--deloitte-blue);
}

.visual-placeholder.green-accent {
  border-top: 4px solid var(--deloitte-green);
}

.visual-placeholder.teal-accent {
  border-top: 4px solid var(--dark-teal);
}

.data-flow {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 200px;
  height: 100px;
