document.addEventListener("DOMContentLoaded", () => {
  // Sticky Navbar logic
  const navbar = document.getElementById('navbar');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 20) {
      navbar.classList.add('scrolled');
    } else {
      navbar.classList.remove('scrolled');
    }
  });

  // Smooth Scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      e.preventDefault();
      const targetId = this.getAttribute('href');
      if (targetId === '#') return;
      const targetElement = document.querySelector(targetId);
      if (targetElement) {
        // Offset for the fixed header
        const headerOffset = 80;
        const elementPosition = targetElement.getBoundingClientRect().top;
        const offsetPosition = elementPosition + window.pageYOffset - headerOffset;
        window.scrollTo({
          top: offsetPosition,
          behavior: "smooth"
        });
      }
    });
  });

  // Intersection Observer for fade-up animations on scroll
  const fadeElements = document.querySelectorAll('.fade-up');
  const observerOptions = {
    root: null,
    rootMargin: '0px',
    threshold: 0.15 // Trigger when 15% of the element is visible
  };
  const observer = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        // Stop observing once the animation has triggered
        observer.unobserve(entry.target);
      }
    });
  }, observerOptions);
  fadeElements.forEach(el => {
    observer.observe(el);
  });

  // Trigger animations for elements already in viewport on load
  setTimeout(() => {
    fadeElements.forEach(el => {
      const rect = el.getBoundingClientRect();
      if (rect.top < window.innerHeight) {
        el.classList.add('visible');
      }
    });
  }, 100);

  // --- 2. AUTHENTICATION & GOOGLE OAUTH (Manual due to Appsmith iframe) ---
  const loginBtn = document.getElementById('login-btn');
  const logoutBtn = document.getElementById('logout-btn');
  const userDisplay = document.getElementById('user-display');

  // Display User Name if logged in (Bridge from Default Model)
  if (typeof appsmith !== 'undefined' && appsmith.model && appsmith.model.isLoggedIn) {
    if (loginBtn) loginBtn.style.display = 'none';
    if (logoutBtn) logoutBtn.style.display = 'inline-block';
    if (userDisplay) {
      userDisplay.style.display = 'inline-block';
      userDisplay.innerText = "Welcome, " + (appsmith.model.userName || "User");
    }
  }
  if (loginBtn) {
    loginBtn.addEventListener('click', e => {
      e.preventDefault();

      // Firebase Auth (signInWithPopup/Redirect) blocked by Appsmith's about:srcdoc iframe.
      // Using manual Google OAuth redirect.
      const rootUrl = "https://accounts.google.com/o/oauth2/v2/auth";

      // DYNAMIC REDIRECT URI FIX
      const cleanRedirectUri = window.location.href.split('/edit')[0];
      const options = {
        redirect_uri: cleanRedirectUri,
        client_id: "142093549187-ji1aq22v36b8g018m556jdvfjgg7ddkg.apps.googleusercontent.com",
        access_type: "offline",
        response_type: "code",
        prompt: "consent",
        scope: ["https://www.googleapis.com/auth/userinfo.profile", "https://www.googleapis.com/auth/userinfo.email"].join(" ")
      };
      const queryString = new URLSearchParams(options).toString();
      window.top.location.href = `${rootUrl}?${queryString}`; // Use window.top to escape iframe
    });
  }
  if (logoutBtn) {
    logoutBtn.addEventListener('click', e => {
      e.preventDefault();
      // Handle manual logout (e.g., clear Appsmith model, redirect)
      if (typeof appsmith !== 'undefined') {
        appsmith.updateModel({
          isLoggedIn: false,
          userName: ""
        });
      }
      loginBtn.style.display = 'inline-flex';
      logoutBtn.style.display = 'none';
      userDisplay.style.display = 'none';
    });
  }
});

