  background-color: var(--light-bg);
  border-top: 1px solid var(--light-gray);
}

.guide-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.guide-card {
  background-color: var(--pure-white);
  padding: 40px 32px;
  border-radius: 8px;
  border: 1px solid var(--light-gray);
  transition: all 0.3s ease;
  position: relative;
}

.guide-card:hover {
  border-color: var(--deloitte-blue);
  transform: translateY(-5px);
  box-shadow: 0 12px 24px rgba(15, 11, 11, 0.04);
}

.guide-icon {
  font-size: 40px;
  margin-bottom: 24px;
}

.guide-card h3 {
  font-size: 22px;
  margin-bottom: 16px;
}

.guide-card p {
  font-size: 16px;
}

/* --- NEW: Tooltips & Highlights --- */
.highlight-word {
  border-bottom: 2px dashed var(--deloitte-green);
  cursor: help;
  transition: all 0.2s;
  display: inline-block;
}

.highlight-word:hover {
  color: var(--pure-white) !important;
  background-color: var(--deloitte-green);
}

.tooltip-wrapper {
  position: relative;
  cursor: help;
}

.tooltip-wrapper-inline {
  position: relative;
  cursor: help;
  display: inline-block;
}

/* The actual tooltip box */
.tooltip-wrapper::after,
.tooltip-wrapper-inline::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  width: 250px;
  background-color: var(--cool-black);
  color: var(--pure-white);
  text-align: center;
  padding: 12px 16px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 100;
  pointer-events: none;
  box-shadow: 0 8px 16px rgba(0,0,0,0.15);
}

/* Arrow for tooltip */
.tooltip-wrapper::before,
.tooltip-wrapper-inline::before {
  content: '';
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  border: 6px solid transparent;
  border-top-color: var(--cool-black);
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 100;
  pointer-events: none;
}

.tooltip-wrapper:hover::after,
.tooltip-wrapper:hover::before,
.tooltip-wrapper-inline:hover::after,
.tooltip-wrapper-inline:hover::before {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(-10px);
}

/* --- Use Cases --- */
.use-cases {
  padding: 100px 0;
  background-color: var(--pure-white);
  border-top: 1px solid var(--light-gray);
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 60px;
}

.use-case-card {
  background-color: var(--light-bg);
  padding: 48px 32px;
  border-radius: 8px;
  border: 1px solid var(--light-gray);
  transition: all 0.3s ease;
}

.use-case-card:hover {
  border-color: var(--deloitte-blue);
  transform: translateY(-5px);
  box-shadow: 0 12px 24px rgba(15, 11, 11, 0.04);
}

.card-icon {
  width: 48px;
  height: 48px;
  color: var(--dark-teal);
  margin-bottom: 24px;
}

.use-case-card h3 {
  font-size: 22px;
  margin-bottom: 16px;
}

.use-case-card p {
  font-size: 16px;
}

/* --- Final CTA --- */
.final-cta {
  background-color: var(--dark-teal);
  padding: 100px 0;
  color: var(--pure-white);
}

.final-cta h2 {
  color: var(--pure-white);
  margin-bottom: 20px;
}

.final-cta p {
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 40px;
  font-size: 20px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.text-center {
  text-align: center;
}

.cta-elevated {
  box-shadow: 0 8px 16px rgba(0,0,0,0.2);
}

/* --- Footer --- */
.site-footer {
  background-color: var(--cool-black);
  padding: 60px 0 30px;
}

.footer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  padding-bottom: 40px;
  margin-bottom: 30px;
}

.brand-text.white {
  color: var(--pure-white);
}

.footer-contact a {
  color: var(--light-gray);
  text-decoration: none;
  font-size: 16px;
  transition: color 0.2s;
}

.footer-contact a:hover {
  color: var(--deloitte-green);
}

.footer-bottom {
  text-align: center;
}

.footer-bottom p {
  font-size: 14px;
  color: var(--cool-gray);
}

/* --- Animation Classes --- */
.fade-up {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s ease-out, transform 0.8s ease-out;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Responsive Adjustments --- */
@media (max-width: 1024px) {
  .hero-container {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .hero-subtitle {
    margin: 0 auto 40px;
  }
  .hero-cta {
    justify-content: center;
  }
  .cards-grid, .guide-grid {
    grid-template-columns: 1fr;
  }
  .feature-row, .feature-row.reverse {
    flex-direction: column;
    gap: 40px;
  }
}

@media (max-width: 768px) {
  .navbar { padding: 0 24px; }
  .nav-links { display: none; }
  .metrics-container { flex-direction: column; gap: 40px; }
  .metric-divider { width: 60px; height: 1px; }
  .hero-title { font-size: 40px; }
}

