srcDoc.css:
:root {
  --deloitte-green: #86BC25;
  --cool-black: #0F0B0B;
  --cool-gray: #75787B;
  --light-gray: #D0D0CE;
  --bg-canvas: #FBFBFB;
  --white: #FFFFFF;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-canvas);
  color: var(--cool-black);
  overflow-x: hidden;
}

/* Dashboard Layout */
.genw-dashboard {
  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
  padding: 40px;
  display: flex;
  flex-direction: column;
  gap: 40px;
}

/* Page Header */
.page-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.green-dot {
  width: 14px;
  height: 14px;
  background-color: var(--deloitte-green);
  border-radius: 50%;
}

.page-title {
  font-size: 28px;
  font-weight: 700;
  color: var(--cool-black);
}

.page-subtitle {
  font-size: 16px;
  color: var(--cool-gray);
  margin-left: 12px;
  font-weight: 400;
}

/* Dashboard Cards */
.dashboard-card {
  background: var(--white);
  border: 1px solid var(--light-gray);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.02);
  transition: all 0.3s ease;
}

.dashboard-card:hover {
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.06);
  transform: translateY(-3px);
}

/* Grids */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
}

.chart-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.insights-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.tables-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

/* KPI Styling */
.kpi-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--cool-gray);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.kpi-desc {
  font-size: 12px;
  color: var(--cool-gray);
  margin-bottom: 16px;
}

.kpi-value {
  font-size: 32px;
  font-weight: 700;
  color: var(--cool-black);
}

.alert-text {
  color: #d32f2f;
}

/* Card Headers */
.panel-header, .block-title, .table-header {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--light-gray);
  color: var(--cool-black);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.canvas-wrapper {
  height: 280px;
  width: 100%;
  position: relative;
}

.highlight-bg {
  border-top: 4px solid var(--deloitte-green);
}

/* Lists & Tables */
.mini-list {
  list-style: none;
}

.mini-list li {
  padding: 12px 0;
  border-bottom: 1px solid var(--bg-canvas);
  display: flex;
  justify-content: space-between;
  font-size: 14px;
}

.giant-stat {
  font-size: 48px;
  font-weight: 700;
  margin: 12px 0;
  color: var(--cool-black);
}

.stat-sub {
  font-size: 13px;
  color: var(--cool-gray);
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  padding: 12px;
  font-size: 12px;
  color: var(--cool-gray);
  border-bottom: 1px solid var(--light-gray);
  text-transform: uppercase;
}

.data-table td {
  padding: 14px 12px;
  font-size: 13px;
  border-bottom: 1px solid var(--bg-canvas);
}

/* Animations */
.fade-up {
  animation: fadeUp 0.8s ease-out forwards;
}

@keyframes fadeUp {
