// --- INTERSECTION OBSERVER FOR ANIMATIONS ---
function initAnimations() {
  const fadeElements = document.querySelectorAll('.fade-up');
  const observer = new IntersectionObserver((entries, obs) => {
    entries.forEach((entry, index) => {
      if (entry.isIntersecting) {
        setTimeout(() => {
          entry.target.classList.add('visible');
        }, index * 80);
        obs.unobserve(entry.target);
      }
    });
  }, {
    root: null,
    rootMargin: '0px',
    threshold: 0.1
  });
  fadeElements.forEach(el => observer.observe(el));
  setTimeout(() => {
    fadeElements.forEach(el => {
      if (el.getBoundingClientRect().top < window.innerHeight) el.classList.add('visible');
    });
  }, 150);
}

// --- MAIN DASHBOARD INITIALIZATION ---
let matrixChart = null;
let trendChart = null;
function initDashboard() {
  // Determine rawData location
  let rawData = [];
  if (typeof appsmith !== 'undefined' && appsmith.model) {
    if (appsmith.model.dashboardData) rawData = appsmith.model.dashboardData;else if (appsmith.model.data) rawData = appsmith.model.data;else if (Array.isArray(appsmith.model)) rawData = appsmith.model;
  }
  if (!rawData || rawData.length === 0) {
    console.warn("Waiting for live data... Retrying...");
    return;
  }

  // --- 1. DATA EXTRACTION & AGGREGATION ---
  let kpis = {
    total: rawData.length,
    highRisk: 0,
    duplicates: 0,
    compliance: 0,
    vendorsFlagged: new Set()
  };
  let lists = {
    vendors: new Set(),
    missingGstin: [],
    violations: new Set(),
    weekend: []
  };
  let highRiskTransactions = [];

  // Aggregators for Charts
  let vendorStats = {};
  let trendData = {};
  rawData.forEach(row => {
    let risk = (row.transaction_risk || row.risk_rating || "").toUpperCase();
    let isHighRisk = risk === "HIGH" || risk === "CRITICAL";
    if (isHighRisk) {
      kpis.highRisk++;
      highRiskTransactions.push(row);
    }
    let flags = [];
    try {
      flags = typeof row.flags_detected === 'string' ? JSON.parse(row.flags_detected) : row.flags_detected || [];
      if (!Array.isArray(flags)) flags = [flags];
    } catch (e) {}
    flags.forEach(f => {
      let type = typeof f === 'object' && f !== null ? f.type || f.flagName : f;
      if (!type) return;
      kpis.compliance++;
      lists.violations.add(type);
      if (type.toLowerCase().includes("duplicate")) kpis.duplicates++;
    });

    // Vendor Logic
    const vId = row.vendor_name || row.vendor_id || "Unknown";
    if (row.vendor_blacklisted === true || row.blacklist_status === true || (row.vendor_risk || "").toUpperCase() === "HIGH") {
      kpis.vendorsFlagged.add(vId);
      lists.vendors.add(`${row.vendor_id} (${vId})`);
    }

    // Aggregate Vendor Stats for Matrix
    if (!vendorStats[vId]) vendorStats[vId] = {
      volume: 0,
      riskScore: 0
    };
    vendorStats[vId].volume += 1;
    vendorStats[vId].riskScore += risk === 'CRITICAL' ? 4 : risk === 'HIGH' ? 3 : risk === 'MEDIUM' ? 2 : 1;

    // Aggregate Trend Data
    const date = row.invoice_date || row.date || row.created_at || "Unknown";
    const dateStr = String(date).split('T')[0];
    if (!trendData[dateStr]) trendData[dateStr] = {
      total: 0,
      flagged: 0
    };
    trendData[dateStr].total++;
    if (isHighRisk || flags.length > 0) trendData[dateStr].flagged++;

    // Lists
    if (!row.gstin || String(row.gstin).trim() === "") lists.missingGstin.push({
      id: row.invoice_id,
      vendor: vId
    });
    if (date !== "Unknown") {
      let d = new Date(date);
      if (d.getDay() === 0 || d.getDay() === 6) {
        lists.weekend.push(row.invoice_id);
      }
    }
  });
  renderKPIs(kpis);
  renderCharts(vendorStats, trendData);
  renderInsights(lists, highRiskTransactions);
  renderTables(highRiskTransactions, rawData);
  initAnimations();
}
if (typeof appsmith !== 'undefined') {
  appsmith.onReady(() => {
    initDashboard();
    appsmith.onModelChange(() => {
      initDashboard();
    });
  });
} else {
  document.addEventListener("DOMContentLoaded", initDashboard);
}

// --- RENDER FUNCTIONS ---

function renderKPIs(kpis) {
  const setText = (id, text) => {
    let el = document.getElementById(id);
    if (el) el.innerText = text;
  };
  setText('kpi-total', kpis.total.toLocaleString());
  setText('kpi-risk', kpis.highRisk.toLocaleString());
  setText('kpi-dup', kpis.duplicates.toLocaleString());
  setText('kpi-comp', kpis.compliance.toLocaleString());
  setText('kpi-vendor', kpis.vendorsFlagged.size.toLocaleString());
}
function renderCharts(vendorStats, trendData) {
  const ctx1 = document.getElementById('matrixChart');
  const ctx2 = document.getElementById('trendChart');
  if (!ctx1 || !ctx2) return;

  // --- CHART 1: OLD STYLE MATRIX BUBBLE CHART ---
  if (matrixChart) matrixChart.destroy();
  matrixChart = new Chart(ctx1.getContext('2d'), {
    type: 'bubble',
    data: {
      // Old style: Every vendor gets its own label and the translucent purple color
      datasets: Object.keys(vendorStats).map((name, i) => ({
        label: name,
        data: [{
          x: vendorStats[name].volume,
          y: vendorStats[name].riskScore / vendorStats[name].volume,
          r: 10
        }],
        backgroundColor: 'rgba(123, 31, 162, 0.6)'
      }))
    },
    options: {
      maintainAspectRatio: false,
      scales: {
        x: {
          title: {
            display: true,
            text: 'Transaction Volume'
          }
        },
        y: {
          title: {
            display: true,
            text: 'Avg Risk Score'
          }
        }
      }
    }
  });

  // --- CHART 2: OLD STYLE ANOMALY TREND LINE CHART ---
  const dates = Object.keys(trendData).sort();
  if (trendChart) trendChart.destroy();
  trendChart = new Chart(ctx2.getContext('2d'), {
    type: 'line',
    data: {
      labels: dates,
      datasets: [
      // Old style: Unfilled lines, Blue (#1976d2) and Red (#d32f2f)
      {
        label: 'Total Invoices',
        data: dates.map(d => trendData[d].total),
        borderColor: '#1976d2',
        fill: false
      }, {
        label: 'Flagged',
        data: dates.map(d => trendData[d].flagged),
        borderColor: '#d32f2f',
        fill: false
      }]
    },
    options: {
      maintainAspectRatio: false
    }
  });
}
function renderInsights(lists, highRiskTransactions) {
  const riskHTML = highRiskTransactions.slice(0, 3).map(r => `<li>${r.vendor_name || r.vendor_id || 'Unknown'} <span>${r.transaction_risk || r.risk_rating || 'HIGH'}</span></li>`).join('');
  const gstinHTML = lists.missingGstin.slice(0, 3).map(g => `<li>${g.vendor} <span>${g.id}</span></li>`).join('');
  const policyArr = Array.from(lists.violations);
  const policyHTML = policyArr.length > 0 ? policyArr.slice(0, 3).map(v => `<li>${v} <span>Flagged</span></li>`).join('') : `<li>No violations <span>0</span></li>`;
  const elRisk = document.getElementById('list-risk');
  const elGstin = document.getElementById('list-gstin');
  const elPolicy = document.getElementById('list-policy');
  const elWeekend = document.getElementById('stat-weekend');
  if (elRisk) elRisk.innerHTML = riskHTML || "<li>No high risk detected</li>";
  if (elGstin) elGstin.innerHTML = gstinHTML || "<li>All GSTINs valid</li>";
  if (elPolicy) elPolicy.innerHTML = policyHTML;
  if (elWeekend) elWeekend.innerText = lists.weekend.length;
}
function renderTables(highRiskTransactions, rawData) {
  const eqBody = document.querySelector('#table-eq tbody');
  const logsBody = document.querySelector('#table-logs tbody');
  if (!eqBody || !logsBody) return;
  if (rawData.length === 0) {
    eqBody.innerHTML = `<tr><td colspan="4">No data available</td></tr>`;
    logsBody.innerHTML = `<tr><td colspan="3">No data available</td></tr>`;
    return;
  }
  const eqRows = highRiskTransactions.length > 0 ? highRiskTransactions : rawData;
  eqBody.innerHTML = eqRows.slice(0, 3).map((d, i) => {
    let issue = "Compliance";
    try {
      let flags = typeof d.flags_detected === 'string' ? JSON.parse(d.flags_detected) : d.flags_detected;
      if (flags && flags.length > 0) issue = flags[0].type || flags[0].flagName || "Compliance";
    } catch (e) {}
    return `<tr><td>${d.invoice_id || 'EQ-' + (101 + i)}</td><td>${d.vendor_name || d.vendor_id || 'Unknown'}</td><td>${issue}</td><td><span style="font-weight: 600; color: #E24C4B;">Escalated</span></td></tr>`;
  }).join('');
  logsBody.innerHTML = rawData.slice(0, 3).map(d => {
    const timeStr = d.created_at ? new Date(d.created_at).toLocaleTimeString() : new Date().toLocaleTimeString();
    return `<tr><td style="color:#75787B">${timeStr}</td><td><strong style="font-weight: 500;">Rule Engine</strong></td><td>Analyzed ${d.invoice_id || 'Transaction'}</td></tr>`;
  }).join('');
}

