// Initialize Icons
lucide.createIcons();
let currentData = [];

// --- 1. Appsmith Data Binding & Rendering ---

function handleViewChange(viewName) {
  document.getElementById('loading-overlay').classList.remove('hidden');
  appsmith.updateModel({
    selectedView: viewName,
    isLoading: true
  });
  appsmith.triggerEvent('onViewChange');
}
function renderDynamicTable(data) {
  const thead = document.getElementById('dynamic-thead');
  const tbody = document.getElementById('dynamic-tbody');

  // Normalize the data to ensure it's always an array
  let safeData = Array.isArray(data) ? data : data?.rows || [];
  if (!safeData || safeData.length === 0) {
    thead.innerHTML = '';
    tbody.innerHTML = '<tr><td class="p-6 text-center text-deloitte-coolGray">No data available for this view.</td></tr>';
    document.getElementById('loading-overlay').classList.add('hidden');
    return;
  }

  // Safely grab columns from the first object
  const columns = Object.keys(safeData[0]);
  let headerHtml = '<tr>';
  columns.forEach(col => {
    const cleanName = col.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
    headerHtml += `<th class="py-3 px-6 font-semibold">${cleanName}</th>`;
  });
  headerHtml += `<th class="py-3 px-6 font-semibold text-right">Actions</th></tr>`;
  thead.innerHTML = headerHtml;
  let rowsHtml = '';
  safeData.forEach(row => {
    rowsHtml += '<tr class="border-b border-deloitte-lightGray hover:bg-gray-50 transition-colors group cursor-pointer" onclick="selectRecord(this)">';
    columns.forEach(col => {
      rowsHtml += `<td class="py-3 px-6">${formatAuditorData(col, row[col])}</td>`;
    });
    rowsHtml += `<td class="py-3 px-6 text-right opacity-0 group-hover:opacity-100 transition-opacity">
        <button class="text-deloitte-blue hover:text-deloitte-darkTeal font-semibold text-xs" onclick="openAssistantForRecord('${row[columns[0]]}')">Analyze</button>
      </td>`;
    rowsHtml += '</tr>';
  });
  tbody.innerHTML = rowsHtml;
  document.getElementById('loading-overlay').classList.add('hidden');
}
function formatAuditorData(key, value) {
  if (value === null || value === undefined) return '<span class="text-gray-400">-</span>';
  const lowerKey = key.toLowerCase();
  if (lowerKey.includes('amount') || lowerKey.includes('value') || lowerKey.includes('spend') || lowerKey.includes('savings')) {
    const num = parseFloat(value);
    if (!isNaN(num)) {
      return `<span class="font-medium text-deloitte-black">${new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR'
      }).format(num)}</span>`;
    }
  }
  if (lowerKey.includes('risk') || lowerKey.includes('status') || lowerKey.includes('match_status') || lowerKey.includes('blacklisted')) {
    let bg = 'bg-gray-100',
      text = 'text-gray-700';
    const valStr = String(value).toUpperCase();
    if (valStr.includes('CRITICAL') || valStr.includes('HIGH') || valStr.includes('MISMATCH') || valStr.includes('MISSING') || valStr === 'TRUE') {
      bg = 'bg-[#FFEBEE]';
      text = 'text-[#C62828]';
    } else if (valStr.includes('MEDIUM') || valStr.includes('PENDING') || valStr.includes('PARTIAL')) {
      bg = 'bg-[#FFF8E1]';
      text = 'text-[#F9A825]';
    } else if (valStr.includes('LOW') || valStr.includes('MATCHED') || valStr.includes('APPROVED') || valStr === 'FALSE') {
      bg = 'bg-[#E8F5E9]';
      text = 'text-[#2E7D32]';
    }
    return `<span class="px-2 py-1 rounded font-bold text-xs ${bg} ${text}">${value}</span>`;
  }
  if (lowerKey.includes('id') || lowerKey.includes('reference') || lowerKey.includes('hash')) {
    return `<span class="font-mono text-deloitte-coolGray text-xs">${value}</span>`;
  }
  if (typeof value === 'object') {
    return `<span class="px-2 py-1 bg-deloitte-canvas border border-deloitte-lightGray text-deloitte-coolGray text-[10px] rounded font-mono truncate max-w-[150px] inline-block" title='${JSON.stringify(value).replace(/'/g, "&#39;")}'>{ JSON }</span>`;
  }
  return `<span class="text-deloitte-black">${value}</span>`;
}

// --- Client-Side Search / Filter ---
// --- Client-Side Search & Advanced Filtering ---

function toggleFilterPanel() {
  const panel = document.getElementById('filter-panel');
  panel.classList.toggle('hidden');
}
function applyAdvancedFilters() {
  const searchQuery = document.getElementById('table-search').value.toLowerCase();
  const riskFilter = document.getElementById('filter-risk').value;
  const minAmount = parseFloat(document.getElementById('filter-amount').value) || 0;
  const filteredData = currentData.filter(row => {
    // 1. Text Search Match
    const matchesSearch = !searchQuery || Object.values(row).some(val => String(val).toLowerCase().includes(searchQuery));

    // 2. Risk/Status Match
    let matchesRisk = true;
    if (riskFilter) {
      // Check the entire row string for keywords related to the filter
      const rowString = JSON.stringify(row).toLowerCase();
      if (riskFilter === 'high_risk') {
        matchesRisk = rowString.includes('critical') || rowString.includes('high') || rowString.includes('true'); // True for blacklisted etc
      } else if (riskFilter === 'mismatch') {
        matchesRisk = rowString.includes('mismatch') || rowString.includes('missing') || rowString.includes('pending');
      } else if (riskFilter === 'clear') {
        matchesRisk = rowString.includes('matched') || rowString.includes('low') || rowString.includes('approved') || rowString.includes('false');
      }
    }

    // 3. Minimum Amount Match
    let matchesAmount = true;
    if (minAmount > 0) {
      // Find any column name that suggests it's an amount/value
      const amountCols = Object.keys(row).filter(k => k.toLowerCase().includes('amount') || k.toLowerCase().includes('value') || k.toLowerCase().includes('spend'));
      if (amountCols.length > 0) {
        // Must have at least one amount column greater than or equal to the minAmount
        matchesAmount = amountCols.some(col => parseFloat(row[col]) >= minAmount);
      } else {
        // If the view doesn't have an amount column, we bypass this filter so we don't accidentally hide everything
        matchesAmount = true;
      }
    }
    return matchesSearch && matchesRisk && matchesAmount;
  });
  renderDynamicTable(filteredData);
}
function clearFilters() {
  document.getElementById('table-search').value = '';
  document.getElementById('filter-risk').value = '';
  document.getElementById('filter-amount').value = '';
  applyAdvancedFilters();
}

// Ensure these are mapped to the window so HTML can trigger them
window.toggleFilterPanel = toggleFilterPanel;
window.applyAdvancedFilters = applyAdvancedFilters;
window.clearFilters = clearFilters;

// --- CSV Export Logic ---
function exportToCSV() {
  const query = document.getElementById('table-search').value.toLowerCase();
  let dataToExport = currentData;
  if (query) {
    dataToExport = currentData.filter(row => {
      return Object.values(row).some(val => String(val).toLowerCase().includes(query));
    });
  }
  if (!dataToExport || dataToExport.length === 0) {
    alert("No data available to export.");
    return;
  }
  const columns = Object.keys(dataToExport[0]);
  let csvContent = "data:text/csv;charset=utf-8," + columns.join(",") + "\n";
  dataToExport.forEach(row => {
    let rowArray = columns.map(col => {
      let val = row[col];
      if (val === null || val === undefined) val = "";
      if (typeof val === 'object') val = JSON.stringify(val);
      val = String(val).replace(/"/g, '""');
      if (val.includes(',') || val.includes('\n') || val.includes('"')) {
        val = `"${val}"`;
      }
      return val;
    });
    csvContent += rowArray.join(",") + "\n";
  });
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  const viewName = document.getElementById('view-selector').value;
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `AuditIQ_${viewName}_Export.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

// --- 2. Chatbot Logic ---
let chatOpen = false;
const assistantData = {
  initialMessage: "<strong>AuditIQ Intelligence</strong><br>I'm ready to analyze financial anomalies, query policy documentation, or draft reports. Select a record from the table to begin contextual analysis.",
  suggestions: ["Analyze High Risk Vendors", "Check Tax Rule Violations", "Summarize latest audits"],
  context: {
    recordRef: ``
  }
};
const history = document.getElementById('chat-history');
const suggestionsBox = document.getElementById('chat-suggestions');
const inputField = document.getElementById('chat-input');
function toggleChat() {
  chatOpen = !chatOpen;
  const chatWindow = document.getElementById('chat-window');
  if (chatOpen) {
    chatWindow.classList.remove('hidden');
    setTimeout(() => {
