function clearFilters() {
  document.getElementById('table-search').value = '';
  document.getElementById('filter-risk').value = '';
  document.getElementById('filter-amount').value = '';
  applyAdvancedFilters();
}

// Ensure these are mapped to the window so HTML can trigger them
window.toggleFilterPanel = toggleFilterPanel;
window.applyAdvancedFilters = applyAdvancedFilters;
window.clearFilters = clearFilters;

// --- CSV Export Logic ---
function exportToCSV() {
  const query = document.getElementById('table-search').value.toLowerCase();
  let dataToExport = currentData;

  if (query) {
      dataToExport = currentData.filter(row => {
        return Object.values(row).some(val => String(val).toLowerCase().includes(query));
      });
  }

  if (!dataToExport || dataToExport.length === 0) {
    alert("No data available to export.");
    return;
  }

  const columns = Object.keys(dataToExport[0]);
  let csvContent = "data:text/csv;charset=utf-8," + columns.join(",") + "\n";

  dataToExport.forEach(row => {
    let rowArray = columns.map(col => {
      let val = row[col];
      if (val === null || val === undefined) val = "";
      if (typeof val === 'object') val = JSON.stringify(val);
      val = String(val).replace(/"/g, '""'); 
      if (val.includes(',') || val.includes('\n') || val.includes('"')) {
        val = `"${val}"`;
      }
      return val;
    });
    csvContent += rowArray.join(",") + "\n";
  });

  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  const viewName = document.getElementById('view-selector').value;

  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `AuditIQ_${viewName}_Export.csv`);
  document.body.appendChild(link);

  link.click();
  document.body.removeChild(link);
}

// --- 2. Chatbot Logic ---
let chatOpen = false;
const assistantData = {
  initialMessage: "<strong>AuditIQ Intelligence</strong><br>I'm ready to analyze financial anomalies, query policy documentation, or draft reports. Select a record from the table to begin contextual analysis.",
  suggestions: ["Analyze High Risk Vendors", "Check Tax Rule Violations", "Summarize latest audits"],
  context: { recordRef: `` }
};

const history = document.getElementById('chat-history');
const suggestionsBox = document.getElementById('chat-suggestions');
const inputField = document.getElementById('chat-input');

function toggleChat() {
  chatOpen = !chatOpen;
  const chatWindow = document.getElementById('chat-window');
  if (chatOpen) {
    chatWindow.classList.remove('hidden');
    setTimeout(() => {
      chatWindow.classList.remove('translate-y-4', 'opacity-0');
      chatWindow.classList.add('translate-y-0', 'opacity-100');
    }, 10);
  } else {
    chatWindow.classList.remove('translate-y-0', 'opacity-100');
    chatWindow.classList.add('translate-y-4', 'opacity-0');
    setTimeout(() => { chatWindow.classList.add('hidden'); }, 300);
  }
}

function initAssistant() {
  history.innerHTML = '';
  appendMessage('bot', assistantData.initialMessage);
  suggestionsBox.innerHTML = '';
  assistantData.suggestions.forEach(s => {
    suggestionsBox.innerHTML += `<button class="px-3 py-1 mb-2 bg-white border border-deloitte-green text-deloitte-green hover:bg-deloitte-green hover:text-white rounded-full text-xs font-semibold transition-colors" onclick="fillInput('${s}')">${s}</button>`;
  });
}

function appendMessage(sender, text) {
  const msgDiv = document.createElement('div');
  msgDiv.className = sender === 'user' 
    ? 'ml-auto max-w-[85%] bg-deloitte-green text-white p-3 rounded-lg rounded-tr-none' 
    : 'mr-auto max-w-[85%] bg-white border border-deloitte-lightGray text-deloitte-black p-3 rounded-lg rounded-tl-none leading-relaxed';
  msgDiv.innerHTML = text;
  history.appendChild(msgDiv);
  history.scrollTop = history.scrollHeight;
}

function fillInput(text) {
    if (suggestionsBox) suggestionsBox.style.display = "none";
    inputField.value = text;
    inputField.focus();
}

function openAssistantForRecord(recordId) {
    assistantData.context.recordRef = recordId;
    if (!chatOpen) toggleChat();
    fillInput(`Analyze record: ${recordId}`);
}

async function sendMessage(text) {
    if (!text) return;
    appendMessage('user', `<b>You:</b> ${text}`);
    inputField.value = ''; 

    const loadingId = 'loading-' + Date.now();
    history.insertAdjacentHTML('beforeend', `<div id="${loadingId}" class="mr-auto max-w-[85%] bg-deloitte-canvas text-deloitte-coolGray p-3 rounded-lg rounded-tl-none animate-pulse border border-deloitte-lightGray"><i>Analyzing data...</i></div>`);
    history.scrollTop = history.scrollHeight;

    const contextString = assistantData.context.recordRef ? `\n\n[System Note: User context focus is on Record ID: ${assistantData.context.recordRef}]` : '';

    try {
        const response = await fetch('https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/a70f8f8e-a621-47a6-a7c9-20dd347bf0e5', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ question: text + contextString }) 
        });

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        const data = await response.json();

        document.getElementById(loadingId).remove();
        let replyText = data.text || data.answer || JSON.stringify(data); 

        replyText = replyText.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                             .replace(/`(.*?)`/g, '<code class="bg-gray-100 px-1 rounded text-red-600 font-mono text-sm">$1</code>')
                             .replace(/\n/g, '<br>');

        appendMessage('bot', replyText);

    } catch (error) {
        document.getElementById(loadingId).remove();
        appendMessage('bot', `<span class="text-[#D32F2F] text-xs"><b>System Error:</b> Secure gateway timeout (${error.message}).</span>`);
    }
}

inputField.addEventListener("keypress", (e) => {
  if (e.key === "Enter") {
    e.preventDefault();
    sendMessage(inputField.value);
  }
});

// --- 3. Appsmith Integration Hooks ---

appsmith.onReady(() => {
    initAssistant();

    // Safety check added here to handle undefined tableData
    if (appsmith.model && (!appsmith.model.tableData || appsmith.model.tableData.length === 0)) {
        handleViewChange(document.getElementById('view-selector').value);
    }
});

appsmith.onModelChange((model) => {
    // Only re-render if the table data actually exists and changed
    if (model.tableData && JSON.stringify(model.tableData) !== JSON.stringify(currentData)) {
        currentData = model.tableData;
        renderDynamicTable(model.tableData);
    }

    if (model.isLoading === false) {
        document.getElementById('loading-overlay').classList.add('hidden');
    }
});

// Expose to global scope for inline HTML handlers
window.handleViewChange = handleViewChange;
window.toggleChat = toggleChat;
window.fillInput = fillInput;
window.openAssistantForRecord = openAssistantForRecord;
window.handleSearch = handleSearch;
window.exportToCSV = exportToCSV;

