  margin: 0;
  color: var(--text-active);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
}

.main-nav {
  flex-grow: 1;
}

.sidebar-footer {
  padding-top: 16px;
  margin-top: auto;
  border-top: 1px solid #1A1A1A;
  flex-shrink: 0;
}

.nav-item {
  padding: 16px 20px 16px 24px;
