// Initialize Icons
setTimeout(() => {
  if (typeof lucide !== 'undefined') lucide.createIcons();
}, 100);
const FLOWISE_API = 'https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/a70f8f8e-a621-47a6-a7c9-20dd347bf0e5';
let queueData = [];
let activeItemId = null;
let currentSessionId = "session-" + Date.now();

// Utility to format Indian Rupees
const formatCurrency = val => {
  const num = parseFloat(val);
  if (isNaN(num)) return "N/A";
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR'
  }).format(num);
};
function renderQueue(dataToRender = queueData) {
  const qList = document.getElementById('queue-list');
  if (!qList) return;
  if (!dataToRender || dataToRender.length === 0) {
    qList.innerHTML = `<div class="p-4 text-center text-sm text-deloitte-coolGray">No pending items in queue.</div>`;
    return;
  }
  qList.innerHTML = dataToRender.map(item => {
    let isActive = item.id === activeItemId;
    let bgClass = isActive ? 'bg-[#F9FBE7] border-deloitte-green shadow-sm ring-1 ring-deloitte-green' : 'bg-white border-deloitte-lightGray hover:border-deloitte-coolGray hover:bg-gray-50';
    let scoreClass = item.score > 90 ? 'text-[#D32F2F] bg-[#FFEBEE]' : 'text-[#F9A825] bg-[#FFF8E1]';
    return `
      <div onclick="selectQueueItem('${item.id}')" class="p-3 rounded-lg border cursor-pointer transition-all ${bgClass}">
         <div class="flex justify-between items-center mb-1">
           <span class="font-semibold text-sm text-deloitte-black">${item.id}</span>
           <span class="text-xs font-bold px-2 py-0.5 rounded ${scoreClass}">${item.score} Risk</span>
         </div>
         <p class="text-xs text-deloitte-coolGray truncate w-48" title="${item.vendor}">${item.vendor}</p>
      </div>
    `;
  }).join('');
}
window.selectQueueItem = function (id) {
  activeItemId = id;
  const record = queueData.find(item => item.id === id);
  if (!record) return;
  renderQueue();

  // 1. Update Explainable AI Text (Smart JSON Parsing)
  const reasoningText = document.getElementById('ai-reasoning-text');
  if (reasoningText) {
    let explanationHtml = "";
    try {
      // Attempt to parse the DB explanation as JSON
      const parsedData = JSON.parse(record.explanation);

      // Handle different possible AI JSON structures
      let flags = [];
      if (Array.isArray(parsedData)) flags = parsedData;else if (parsedData.verifiedFlags) flags = parsedData.verifiedFlags;else if (parsedData.riskResult && parsedData.riskResult.flags) flags = parsedData.riskResult.flags;else if (parsedData.flags) flags = parsedData.flags;
      if (flags && flags.length > 0) {
        explanationHtml = `<div class="space-y-3 mt-2">`;
        flags.forEach(flag => {
          // Normalize keys since AI might generate slightly different casing
          const severity = String(flag.Severity || flag.severity || flag['Severity Level'] || flag.riskLevel || 'INFO').toUpperCase();
          const type = flag.Flag_Type || flag.flag_type || flag['Flag Type'] || flag.flagName || flag.type || flag.rule || 'Anomaly';
          const detail = flag.Evidence || flag.evidence || flag['Evidence/Details'] || flag.description || flag.details || flag.reasoning || 'No details provided.';
          let sevColor = 'bg-gray-100 text-gray-700';
          let borderColor = 'border-gray-300';
          if (severity.includes('CRITICAL')) {
            sevColor = 'bg-[#FFEBEE] text-[#D32F2F]';
            borderColor = 'border-[#EF9A9A]';
          } else if (severity.includes('HIGH')) {
            sevColor = 'bg-[#FFF8E1] text-[#F9A825]';
            borderColor = 'border-[#FFE082]';
          } else if (severity.includes('MEDIUM')) {
            sevColor = 'bg-[#FFF3E0] text-[#F57C00]';
            borderColor = 'border-[#FFCC80]';
          }
          explanationHtml += `
                    <div class="text-sm border-l-2 pl-3 py-1 ${borderColor}">
                        <span class="text-[10px] font-bold px-1.5 py-0.5 rounded-sm ${sevColor} mr-2 uppercase tracking-wider">${severity}</span>
                        <strong class="text-deloitte-black">${type}:</strong> 
                        <span class="text-deloitte-coolGray leading-relaxed block mt-1">${detail}</span>
                    </div>`;
        });
        explanationHtml += `</div>`;
      } else {
        // If it parses but has no flags array, fallback to a clean string
        let cleanText = record.explanation.replace(/[{}"[\]]/g, ' ').trim();
        explanationHtml = `<p class="text-deloitte-coolGray text-sm leading-relaxed">${cleanText}</p>`;
      }
    } catch (e) {
      // Fallback: If it's standard text (not JSON), clean up any markdown and display it
      let text = record.explanation || `Anomaly detected for ${record.vendor}. Risk score is ${record.score}.`;
      explanationHtml = `<p class="text-deloitte-coolGray text-sm leading-relaxed">${text.replace(/#/g, '').trim()}</p>`;
    }
    reasoningText.innerHTML = `${explanationHtml} <button onclick="fillInput('Show me the database evidence for ${record.id}')" class="text-deloitte-blue hover:text-deloitte-darkTeal font-semibold text-xs mt-4 transition-colors flex items-center gap-1"><i data-lucide="database" class="w-3 h-3"></i> Ask AI for Deep Dive</button>`;
    if (typeof lucide !== 'undefined') lucide.createIcons();
  }

  // 2. Update 3-Way Match Block
  document.getElementById('ui-po-id').innerText = record.po_id || "Missing";
  document.getElementById('ui-po-amt').innerText = formatCurrency(record.po_amount);
  document.getElementById('ui-grn-id').innerText = record.grn_id || "Missing";
  document.getElementById('ui-grn-amt').innerText = formatCurrency(record.grn_amount);
  document.getElementById('ui-inv-id').innerText = record.id;
  document.getElementById('ui-inv-amt').innerText = formatCurrency(record.invoice_amount);
  document.getElementById('ui-match-status').innerText = record.match_status || "Unknown";

  // Update Invoice Card styling based on Match Status
  const invCard = document.getElementById('ui-inv-card');
  const invBorder = document.getElementById('ui-inv-border');
  const invHeader = document.getElementById('ui-inv-header');
  const invText = document.getElementById('ui-inv-text');
  const statusSafe = String(record.match_status || "").toLowerCase();
  if (statusSafe.includes('matched') && !statusSafe.includes('mismatch')) {
    invCard.className = "flex-1 bg-[#E8F5E9] border-[#C8E6C9] rounded border p-4 relative overflow-hidden transition-all";
    invBorder.className = "absolute top-0 left-0 w-1 h-full bg-[#2E7D32]";
    invHeader.className = "text-xs font-bold uppercase tracking-wider mb-2 text-[#2E7D32]";
    invText.className = "text-sm font-mono space-y-1 text-[#1B5E20]";
  } else {
    invCard.className = "flex-1 bg-[#FFEBEE] border-[#FFCDD2] rounded border p-4 relative overflow-hidden transition-all";
    invBorder.className = "absolute top-0 left-0 w-1 h-full bg-[#D32F2F]";
    invHeader.className = "text-xs font-bold uppercase tracking-wider mb-2 text-[#D32F2F]";
    invText.className = "text-sm font-mono space-y-1 text-[#B71C1C]";
  }

  // 3. Update Chain of Evidence (Logs)
  const evidenceContainer = document.getElementById('ui-evidence-chain');
  if (evidenceContainer) {
    let chainData = [];
