    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            const term = e.target.value.toLowerCase();
            const filtered = queueData.filter(d => String(d.id).toLowerCase().includes(term) || String(d.vendor).toLowerCase().includes(term));
            renderQueue(filtered);
        });
    }
}, 200);

// --- Chatbot Logic ---
let chatOpen = false;
window.toggleChat = function() {
  chatOpen = !chatOpen;
  const chatWindow = document.getElementById('chat-window');
  if (chatOpen) {
    chatWindow.classList.remove('hidden');
    setTimeout(() => { chatWindow.classList.remove('translate-y-4', 'opacity-0'); chatWindow.classList.add('translate-y-0', 'opacity-100'); }, 10);
  } else {
    chatWindow.classList.remove('translate-y-0', 'opacity-100'); chatWindow.classList.add('translate-y-4', 'opacity-0');
    setTimeout(() => { chatWindow.classList.add('hidden'); }, 300);
  }
}

const assistantData = {
  initialMessage: "<strong>AuditIQ Review Assistant</strong><br>I am connected to the active exception context. How can I help you resolve this?",
  suggestions: ["Explain 3-way match failure", "Draft rejection justification", "Summarize chain of evidence"],
  context: { recordHtml: ``, evidenceLinks: [] }
};

function initAssistant() {
  const history = document.getElementById('chat-history');
  const suggestionsBox = document.getElementById('chat-suggestions');
  if (!history || !suggestionsBox) return;
  history.innerHTML = ''; suggestionsBox.innerHTML = '';
  appendMessage('bot', assistantData.initialMessage);
  assistantData.suggestions.forEach(s => {
    suggestionsBox.innerHTML += `<button class="px-3 py-1 bg-white border border-deloitte-green text-deloitte-green hover:bg-deloitte-green hover:text-white rounded-full text-xs font-semibold transition-colors" onclick="fillInput('${s}')">${s}</button>`;
  });
  renderQueue();
}

function appendMessage(sender, text) {
  const history = document.getElementById('chat-history');
  if (!history) return;
  const msgDiv = document.createElement('div');
  msgDiv.className = sender === 'user' ? 'ml-auto max-w-[85%] bg-deloitte-green text-white p-3 rounded-lg rounded-tr-none shadow-sm' : 'mr-auto max-w-[85%] bg-white border border-deloitte-lightGray text-deloitte-black p-3 rounded-lg rounded-tl-none shadow-sm';
  msgDiv.innerHTML = text; history.appendChild(msgDiv); history.scrollTop = history.scrollHeight;
}

window.fillInput = function(text) {
    const suggestionsBox = document.getElementById('chat-suggestions');
    const inputField = document.getElementById('chat-input');
    if (suggestionsBox) suggestionsBox.style.display = "none";
    if(inputField) { inputField.value = text; inputField.focus(); }
}

async function sendMessage(text) {
    const history = document.getElementById('chat-history');
    const inputField = document.getElementById('chat-input');
    if (!text || !history) return;

    appendMessage('user', `<b>You:</b> ${text}`);
    if(inputField) inputField.value = ''; 
    const loadingId = 'loading-' + Date.now();
    history.innerHTML += `<div id="${loadingId}" class="mr-auto max-w-[85%] bg-deloitte-canvas text-deloitte-coolGray p-3 rounded-lg rounded-tl-none animate-pulse border border-deloitte-lightGray shadow-sm"><i>Thinking...</i></div>`;
    history.scrollTop = history.scrollHeight;

    const contextString = assistantData.context.recordHtml ? `\n\n[System Note: Context: ${assistantData.context.recordHtml}]` : '';

    try {
        const response = await fetch(FLOWISE_API, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ question: text + contextString }) });
        const data = await response.json();
        const loadingEl = document.getElementById(loadingId);
        if(loadingEl) loadingEl.remove();

        let replyText = data.text || data.answer || JSON.stringify(data);
        replyText = replyText.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/`(.*?)`/g, '<code class="bg-[#F3F4F6] px-1 py-0.5 rounded text-[#D32F2F] font-mono text-sm">$1</code>').replace(/\n/g, '<br>');
        appendMessage('bot', replyText);
    } catch (error) {
        const loadingEl = document.getElementById(loadingId);
        if(loadingEl) loadingEl.remove();
        appendMessage('bot', `<span class="text-[#D32F2F] text-xs"><b>System Error:</b> Could not reach AI.</span>`);
    }
}

setTimeout(() => {
    const inputField = document.getElementById('chat-input');
    if (inputField) {
        inputField.addEventListener("keypress", function(e) {
          if (e.key === "Enter") {
            e.preventDefault(); sendMessage(inputField.value);
            const suggestionsBox = document.getElementById('chat-suggestions');
            if (suggestionsBox) suggestionsBox.style.display = "none";
          }
        });
    }
}, 200);

// Appsmith Data Binding
if (typeof appsmith !== 'undefined') {
    appsmith.onReady(() => { initAssistant(); });
    appsmith.onModelChange((model) => {
        if (model && Array.isArray(model.queueData) && model.queueData.length > 0) {
            queueData = model.queueData;
            if (!activeItemId && queueData.length > 0) {
                activeItemId = queueData[0].id;
                window.selectQueueItem(activeItemId);
            } else {
                renderQueue();
            }
        }
    });
} else {
    initAssistant();
}

