:root {
  --deloitte-green: #86BC25;
  --sidebar-bg: #000000;
  --active-bg: #1E1E1E; /* Dark gray for active item */
  --text-inactive: #75838A; /* Muted gray-blue */
  --text-active: #FFFFFF;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--sidebar-bg);
}

.sidebar-container {
  width: 100%;
  height: 100vh;
  background-color: var(--sidebar-bg);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

/* Hide scrollbar for clean look */
.sidebar-container::-webkit-scrollbar {
  width: 0px;
}

.sidebar-header {
  padding: 24px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
  flex-shrink: 0;
}

.green-dot {
  width: 14px;
  height: 14px;
  background-color: var(--deloitte-green);
  border-radius: 50%;
  flex-shrink: 0;
}

.brand-text {
  margin: 0;
  color: var(--text-active);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
}

.main-nav {
  flex-grow: 1;
}

.sidebar-footer {
  padding-top: 16px;
  margin-top: auto;
  border-top: 1px solid #1A1A1A;
  flex-shrink: 0;
}

.nav-item {
  padding: 16px 20px 16px 24px;
  color: var(--text-inactive);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease-in-out;
  border-left: 6px solid transparent;
  display: flex;
  align-items: center;
  gap: 14px;
}

.nav-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

/* Hover state */
.nav-item:hover:not(.active) {
  color: var(--text-active);
  background-color: #0A0A0A;
}

/* Active state */
.nav-item.active {
  background-color: var(--active-bg);
  color: var(--text-active);
  border-left: 6px solid var(--deloitte-green);
}

.nav-item.active .nav-icon {
  color: var(--deloitte-green);
}

