import React from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm'
import reactDom from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm'
import * as d3 from 'https://cdn.jsdelivr.net/npm/d3@7/+esm'

const { useState, useEffect, useRef } = React;
const FLOWISE_API = 'https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/a70f8f8e-a621-47a6-a7c9-20dd347bf0e5';

// ─── Stateless presentational components ───
function GreenDot() { return <span className="green-dot" style={{display: 'inline-block', width:'10px', height:'10px', backgroundColor:'#86BC25', borderRadius:'50%', marginRight:'8px'}} />; }

function KpiCard(props) {
  return (
    <div className={`kpi-card kpi-${props.accent}`} style={{backgroundColor:'#fff', padding:'16px', borderRadius:'12px', border:'1px solid #D0D0CE', borderLeft:`4px solid ${props.color || '#86BC25'}`, boxShadow:'0 1px 2px rgba(0,0,0,0.05)'}}>
      <div className="kpi-body">
        <p className="kpi-label" style={{fontSize:'11px', fontWeight:'bold', color:'#75787B', textTransform:'uppercase', letterSpacing:'0.5px'}}>{props.label}</p>
        <p className="kpi-value" style={{fontSize:'24px', fontWeight:'900', marginTop:'4px', color: props.valueColor || '#0F0B0B'}}>{props.value}</p>
        {props.trend ? <p className="kpi-trend" style={{fontSize:'12px', color:'#75787B', marginTop:'4px'}}>{props.trend}</p> : null}
      </div>
    </div>
  );
}

function ScoreBar(props) {
  const score = props.score;
  const fillClass = score > 70 ? '#D32F2F' : score > 40 ? '#F9A825' : '#2E7D32';
  const label = score > 70 ? 'High' : score > 40 ? 'Med' : 'Low';
  const pillBg = score > 70 ? '#FFEBEE' : score > 40 ? '#FFF8E1' : '#E8F5E9';

  return (
    <div style={{display:'flex', alignItems:'center', gap:'8px'}}>
      <div style={{width:'60px', height:'6px', backgroundColor:'#F3F4F6', borderRadius:'3px', overflow:'hidden'}}>
        <div style={{ width: `${score}%`, backgroundColor: fillClass, height: '100%' }} />
      </div>
      <span style={{fontWeight:'bold', fontSize:'13px', color: fillClass}}>{score}</span>
      <span style={{fontSize:'10px', fontWeight:'bold', padding:'2px 6px', borderRadius:'4px', backgroundColor: pillBg, color: fillClass}}>{label}</span>
    </div>
  );
}

// ─── D3.js Dynamic Network Graph ───
function NetworkGraph({ vendors }) {
  const svgRef = useRef(null);

  useEffect(() => {
    if (!vendors || vendors.length === 0) return;

    const nodes = [];
    const links = [];
    const entityMap = new Map();

    vendors.forEach(v => {
      const dir = v.rawData?.shared_director;
      const ip = v.rawData?.shared_ip_address;

      if (dir || ip) {
        if (!entityMap.has(v.vendorId)) {
          entityMap.set(v.vendorId, { id: v.vendorId, label: v.name.split(' ')[0], full_name: v.name, type: 'vendor', risk: v.isDanger });
          nodes.push(entityMap.get(v.vendorId));
        }

        if (dir) {
          const dirId = `DIR_${dir.replace(/\s+/g, '')}`;
          if (!entityMap.has(dirId)) {
            entityMap.set(dirId, { id: dirId, label: 'DIR', full_name: `Director: ${dir}`, type: 'director' });
            nodes.push(entityMap.get(dirId));
          }
          links.push({ source: v.vendorId, target: dirId });
        }

        if (ip) {
          const ipId = `IP_${ip.replace(/\./g, '')}`;
          if (!entityMap.has(ipId)) {
            entityMap.set(ipId, { id: ipId, label: 'IP', full_name: `IP: ${ip}`, type: 'ip' });
            nodes.push(entityMap.get(ipId));
          }
          links.push({ source: v.vendorId, target: ipId });
        }
      }
    });

    if (nodes.length === 0) {
        d3.select(svgRef.current).selectAll("*").remove();
        return; 
    }

    const width = 600;
    const height = 240;
    const svg = d3.select(svgRef.current)
      .attr("viewBox", [0, 0, width, height])
      .style("width", "100%")
      .style("height", "100%");

    svg.selectAll("*").remove(); 

    const simulation = d3.forceSimulation(nodes)
      .force("link", d3.forceLink(links).id(d => d.id).distance(100))
      .force("charge", d3.forceManyBody().strength(-400))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collide", d3.forceCollide().radius(35));

    const link = svg.append("g")
      .attr("stroke", "#D32F2F")
      .attr("stroke-opacity", 0.6)
      .attr("stroke-width", 2)
      .attr("stroke-dasharray", "5,5")
      .selectAll("line")
      .data(links)
      .join("line");

    const node = svg.append("g")
      .selectAll("g")
      .data(nodes)
      .join("g")
      .call(drag(simulation));

    node.append("circle")
      .attr("r", d => d.type === 'vendor' ? 22 : 18)
      .attr("fill", d => d.type === 'vendor' ? '#fff' : (d.type === 'director' ? '#0F0B0B' : '#75787B'))
      .attr("stroke", d => d.type === 'vendor' ? (d.risk ? '#D32F2F' : '#86BC25') : '#F9A825')
      .attr("stroke-width", 3)
      .style("cursor", "pointer");

    node.append("text")
      .text(d => d.type === 'vendor' ? d.label.substring(0,6) : d.label)
      .attr("text-anchor", "middle")
      .attr("dy", 4)
      .attr("fill", d => d.type === 'vendor' ? '#0F0B0B' : '#fff')
      .attr("font-size", d => d.type === 'vendor' ? "11px" : "10px")
      .attr("font-weight", "bold")
      .style("pointer-events", "none");

    node.append("title").text(d => d.full_name);

    simulation.on("tick", () => {
      link.attr("x1", d => Math.max(22, Math.min(width - 22, d.source.x)))
          .attr("y1", d => Math.max(22, Math.min(height - 22, d.source.y)))
          .attr("x2", d => Math.max(18, Math.min(width - 18, d.target.x)))
          .attr("y2", d => Math.max(18, Math.min(height - 18, d.target.y)));

      node.attr("transform", d => `translate(${Math.max(22, Math.min(width - 22, d.x))},${Math.max(22, Math.min(height - 22, d.y))})`);
    });

    function drag(simulation) {
      function dragstarted(event) {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        event.subject.fx = event.subject.x;
        event.subject.fy = event.subject.y;
      }
      function dragged(event) {
        event.subject.fx = event.x;
        event.subject.fy = event.y;
      }
      function dragended(event) {
        if (!event.active) simulation.alphaTarget(0);
        event.subject.fx = null;
        event.subject.fy = null;
      }
      return d3.drag()
        .on("start", dragstarted)
        .on("drag", dragged)
        .on("end", dragended);
    }

    return () => simulation.stop(); 
  }, [vendors]);

  const hasCollusion = vendors.some(v => v.rawData?.shared_director || v.rawData?.shared_ip_address);

  return (
    <div className="network-canvas" style={{position:'relative', backgroundColor:'#0F0B0B', padding:'20px', borderRadius:'0 0 12px 12px', height:'260px', overflow:'hidden'}}>
      {!hasCollusion ? (
        <div style={{display:'flex', height:'100%', alignItems:'center', justifyContent:'center', color:'#86BC25', flexDirection:'column'}}>
            <i data-lucide="shield-check" style={{width:'40px', height:'40px', marginBottom:'8px'}}></i>
            <p style={{fontWeight:'bold', fontSize:'14px'}}>No Collusion Networks Detected</p>
            <p style={{fontSize:'12px', color:'#75787B'}}>Vendor ecosystem is currently clean.</p>
        </div>
      ) : (
        <>
            <svg ref={svgRef} style={{width:'100%', height:'100%'}}></svg>
            <div style={{position:'absolute', bottom:'20px', left:'20px', backgroundColor:'rgba(211,47,47,0.1)', border:'1px solid #D32F2F', padding:'12px', borderRadius:'8px', color:'#fff', maxWidth:'80%', pointerEvents:'none'}}>
              <span style={{fontSize:'10px', fontWeight:'bold', color:'#FFCDD2', display:'block', marginBottom:'4px'}}>⚠ COLLUSION ALERT</span>
              <p style={{fontSize:'12px', margin:0}}>Network indicates shared infrastructure or leadership among vendors.</p>
            </div>
            <div style={{position:'absolute', top:'20px', right:'20px', display:'flex', gap:'12px', fontSize:'10px', color:'#D0D0CE', fontWeight:'bold'}}>
                <span style={{display:'flex', alignItems:'center', gap:'4px'}}><div style={{width:'10px', height:'10px', borderRadius:'50%', backgroundColor:'#fff', border:'2px solid #86BC25'}}/> Vendor</span>
                <span style={{display:'flex', alignItems:'center', gap:'4px'}}><div style={{width:'10px', height:'10px', borderRadius:'50%', backgroundColor:'#0F0B0B', border:'2px solid #F9A825'}}/> Director</span>
                <span style={{display:'flex', alignItems:'center', gap:'4px'}}><div style={{width:'10px', height:'10px', borderRadius:'50%', backgroundColor:'#75787B', border:'2px solid #F9A825'}}/> IP Addr</span>
            </div>
        </>
      )}
    </div>
  );
}

function RiskMetrics(props) {
  const validPct = props.total ? Math.round((props.validGst / props.total) * 100) : 0;
  return (
    <div style={{padding:'20px', display:'flex', flexDirection:'column', gap:'16px'}}>
      <div style={{display:'flex', justifyContent:'space-between', alignItems:'center'}}>
        <div>
          <p style={{fontSize:'14px', fontWeight:'bold', margin:0}}>GSTIN Active</p>
          <p style={{fontSize:'11px', color:'#75787B', margin:0}}>{validPct}% of total</p>
        </div>
        <span style={{fontSize:'24px', fontWeight:'900', color:'#2E7D32'}}>{props.validGst.toLocaleString()}</span>
      </div>
      <div style={{width:'100%', backgroundColor:'#F3F4F6', height:'6px', borderRadius:'3px'}}>
         <div style={{width:`${validPct}%`, backgroundColor:'#86BC25', height:'100%', borderRadius:'3px'}} />
      </div>
      <div style={{height:'1px', backgroundColor:'#D0D0CE', margin:'8px 0'}} />
      <div style={{display:'flex', justifyContent:'space-between', alignItems:'center'}}>
        <div>
          <p style={{fontSize:'14px', fontWeight:'bold', margin:0}}>GSTIN Suspended / Mismatch</p>
          <p style={{fontSize:'11px', color:'#75787B', margin:0}}>Requires verification</p>
        </div>
        <span style={{fontSize:'24px', fontWeight:'900', color:'#D32F2F'}}>{props.suspendedGst}</span>
      </div>
      <div style={{backgroundColor:'#FFF8E1', padding:'12px', borderRadius:'8px', display:'flex', gap:'12px', alignItems:'center', marginTop:'8px'}}>
        <span style={{fontSize:'20px'}}>🔗</span>
        <div>
          <p style={{fontSize:'11px', fontWeight:'bold', color:'#F57F17', textTransform:'uppercase', margin:0}}>Shared IP Clusters</p>
          <p style={{fontSize:'16px', fontWeight:'900', margin:0}}>{props.clusters} <span style={{fontSize:'12px', fontWeight:'normal'}}>groups</span></p>
        </div>
      </div>
    </div>
  );
}

function Card(props) {
  return (
    <div style={{backgroundColor:'#fff', borderRadius:'12px', border:'1px solid #D0D0CE', overflow:'hidden', display:'flex', flexDirection:'column'}}>
      <div style={{padding:'16px 20px', borderBottom:'1px solid #D0D0CE', display:'flex', justifyContent:'space-between', alignItems:'center', backgroundColor:'#FBFBFB'}}>
        <span style={{fontWeight:'bold', fontSize:'16px'}}>{props.title}</span>
        {props.extra}
      </div>
      <div style={{flex:1, ...props.bodyStyle}}>
        {props.children}
      </div>
    </div>
  );
}

// ─── Chatbot Component (React Hooks) ───
function Chatbot() {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [history, setHistory] = useState([
    { sender: 'bot', text: "<strong>Vendor Intelligence AI</strong><br>I can analyze specific vendor profiles, summarize collusion risks, or draft compliance emails. What do you need?" }
  ]);
  const [loading, setLoading] = useState(false);
  const endRef = useRef(null);

  const suggestions = ["Analyze shell company risk", "Draft vendor suspension notice", "Review recent blacklists"];

  useEffect(() => {
    if (endRef.current) endRef.current.scrollIntoView({ behavior: 'smooth' });
    if (isOpen) setTimeout(() => { if (typeof lucide !== 'undefined') lucide.createIcons(); }, 50);
  }, [history, isOpen]);

  const parseMarkdown = (text) => {
      if (!text) return "";
      return text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                 .replace(/`(.*?)`/g, '<code style="background:#F3F4F6; padding:2px 4px; border-radius:4px; color:#D32F2F; font-family:monospace; font-size:12px;">$1</code>')
                 .replace(/\n/g, '<br>');
  };

  const handleSend = async (textToSend) => {
    const text = textToSend || input;
    if (!text.trim()) return;

    setHistory(prev => [...prev, { sender: 'user', text: `<b>You:</b> ${text}` }]);
    setInput('');
    setLoading(true);

    try {
        const response = await fetch(FLOWISE_API, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ question: text + "\n[System Note: Context is Vendor Intelligence and Risk Management]" }) 
        });
        const data = await response.json();
        let reply = data.text || data.answer || JSON.stringify(data);
        setHistory(prev => [...prev, { sender: 'bot', text: parseMarkdown(reply) }]);
    } catch (e) {
        setHistory(prev => [...prev, { sender: 'bot', text: `<span style="color:#D32F2F; font-size:12px;"><b>Error:</b> AI connection timeout.</span>` }]);
    }
    setLoading(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end gap-4" style={{position: 'fixed', bottom: '24px', right: '24px', zIndex: 50, display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '16px'}}>
      {isOpen && (
        <div style={{width:'320px', backgroundColor:'#fff', border:'1px solid #D0D0CE', borderRadius:'16px', overflow:'hidden', boxShadow:'0 10px 25px rgba(0,0,0,0.1)', display:'flex', flexDirection:'column'}}>
          <div style={{backgroundColor:'#0F0B0B', color:'#fff', padding:'16px', display:'flex', justifyContent:'space-between', alignItems:'center'}}>
            <div style={{display:'flex', alignItems:'center', gap:'8px'}}>
              <i data-lucide="bot" style={{width:'20px', height:'20px', color:'#86BC25'}}></i>
              <h3 style={{fontWeight:'bold', margin:0, fontSize:'14px'}}>AuditIQ Assistant</h3>
            </div>
            <button onClick={() => setIsOpen(false)} style={{background:'none', border:'none', color:'#D0D0CE', cursor:'pointer'}}><i data-lucide="x" style={{width:'20px', height:'20px'}}></i></button>
          </div>
          <div style={{height:'350px', display:'flex', flexDirection:'column'}}>
            <div style={{flex:1, overflowY:'auto', padding:'16px', backgroundColor:'#FBFBFB', display:'flex', flexDirection:'column', gap:'12px'}}>
              {history.map((msg, i) => (
                <div key={i} style={{
                    maxWidth:'85%', padding:'12px', borderRadius:'8px', fontSize:'13px', lineHeight:'1.5',
                    alignSelf: msg.sender === 'user' ? 'flex-end' : 'flex-start',
                    backgroundColor: msg.sender === 'user' ? '#86BC25' : '#fff',
                    color: msg.sender === 'user' ? '#fff' : '#0F0B0B',
                    border: msg.sender === 'bot' ? '1px solid #D0D0CE' : 'none',
                    borderTopRightRadius: msg.sender === 'user' ? 0 : '8px',
                    borderTopLeftRadius: msg.sender === 'bot' ? 0 : '8px'
                }} dangerouslySetInnerHTML={{__html: msg.text}} />
              ))}
              {loading && <div style={{alignSelf:'flex-start', padding:'12px', backgroundColor:'#fff', border:'1px solid #D0D0CE', borderRadius:'8px', borderTopLeftRadius:0, fontSize:'13px', color:'#75787B', fontStyle:'italic'}}>Thinking...</div>}
              <div ref={endRef} />
            </div>
            {history.length === 1 && (
              <div style={{padding:'0 16px 12px', backgroundColor:'#FBFBFB', display:'flex', flexWrap:'wrap', gap:'8px'}}>
                {suggestions.map(s => (
                  <button key={s} onClick={() => handleSend(s)} style={{padding:'4px 12px', backgroundColor:'#fff', border:'1px solid #86BC25', color:'#86BC25', borderRadius:'999px', fontSize:'11px', fontWeight:'bold', cursor:'pointer'}}>{s}</button>
                ))}
              </div>
            )}
            <div style={{padding:'12px', backgroundColor:'#fff', borderTop:'1px solid #D0D0CE'}}>
              <input 
                type="text" 
                value={input} 
                onChange={e => setInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="Ask AI..." 
                style={{width:'100%', padding:'8px 12px', border:'1px solid #D0D0CE', borderRadius:'8px', fontSize:'13px', outline:'none', boxSizing:'border-box'}} 
              />
            </div>
          </div>
        </div>
      )}
      <button onClick={() => setIsOpen(!isOpen)} style={{width:'56px', height:'56px', backgroundColor:'#86BC25', color:'#fff', borderRadius:'50%', border:'none', boxShadow:'0 4px 12px rgba(134,188,37,0.4)', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center'}}>
        <i data-lucide="message-square" style={{width:'24px', height:'24px'}}></i>
      </button>
    </div>
  );
}

// ─── Main App as Class Component ───
class App extends React.Component {
  constructor(props) {
    super(props);
    this.state = { search: '', filter: 'all' };
  }

  componentDidMount() {
    setTimeout(() => { if (typeof lucide !== 'undefined') lucide.createIcons(); }, 100);
  }

  componentDidUpdate() {
    setTimeout(() => { if (typeof lucide !== 'undefined') lucide.createIcons(); }, 50);
  }

  sendVendorEmail = async (record, event) => {
    const btn = event.currentTarget;
    const originalHTML = btn.innerHTML;
    const originalPointerEvents = btn.style.pointerEvents;

    // Set Loading State
    btn.innerHTML = `Sending...`;
    btn.disabled = true;
    btn.style.pointerEvents = 'none'; // Prevent hover overriding states
    btn.style.opacity = "0.7";

    const issue = record.flags.length > 0 ? record.flags.join(", ") : "Routine Compliance Check";

    const payload = {
      question: JSON.stringify({
        intent: "vendor_outreach",
        vendor: record.name,
        issue: issue,
        recipient: "rimdaas30@gmail.com"
      })
    };

    try {
      const response = await fetch("https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/7d82d3ee-ddfd-46ee-9211-b1228072f3c9", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      const result = await response.json();

      // UI Success State
      btn.textContent = "Sent ✓";
      btn.style.backgroundColor = "#2e7d32"; // Success green
      btn.style.color = "#fff";
      btn.style.borderColor = "#2e7d32";
      btn.style.opacity = "1";
    } catch (error) {
      console.error("Outreach API Error:", error);
      // UI Error State
      btn.textContent = "Failed ✕";
      btn.style.backgroundColor = "#d32f2f"; // Error red
      btn.style.color = "#fff";
      btn.style.borderColor = "#d32f2f";
      btn.style.opacity = "1";
    }

    // Reset button after 3 seconds
    setTimeout(() => {
      btn.innerHTML = originalHTML;
      btn.disabled = false;
      btn.style.pointerEvents = originalPointerEvents;
      btn.style.backgroundColor = "#fff";
      btn.style.color = "#0F0B0B";
      btn.style.borderColor = "#D0D0CE";
      if (typeof lucide !== 'undefined') lucide.createIcons({root: btn});
    }, 3000);
  };

  render() {
    const { search, filter } = this.state;
    const rawData = appsmith.model;

    let vendors = [];
    if (Array.isArray(rawData)) vendors = rawData;
    else if (rawData && Array.isArray(rawData.vendorData)) vendors = rawData.vendorData;
    else if (rawData && typeof rawData === 'object') vendors = Object.values(rawData);

    if (!vendors || vendors.length === 0) {
      return (
        <div style={{padding:'40px', textAlign:'center', color:'#75787B'}}>
          <div style={{fontSize:'40px', marginBottom:'16px'}}>📊</div>
          <h3 style={{color:'#0F0B0B'}}>No vendor data loaded</h3>
          <p>Configure the fetch_vendor_intel API in Appsmith to begin analysis.</p>
        </div>
      );
    }

    let validGst = 0, suspendedGst = 0, blacklistedCount = 0, highRiskCount = 0, totalScore = 0;
    let clusters = 0;
    const sharedIPs = new Set();
    const sharedDirs = new Set();

    // Dynamically Map Real DB Fields
    const tableData = vendors.map((v, i) => {
      const score = parseFloat(v.avg_risk_score) || 0;
      const shellScore = parseInt(v.shell_risk_score) || 0;
      const gstinStatus = v.gstin_status || 'Unknown';
      const isBlacklisted = v.blacklisted === true || v.blacklisted === 't';
      const isHighRisk = score >= 70 || isBlacklisted;

      if (gstinStatus.toUpperCase().includes('ACTIVE')) validGst++; else suspendedGst++;
      if (isBlacklisted) blacklistedCount++;
      if (isHighRisk) highRiskCount++;
      totalScore += score;

      const flags = [];
      if (isBlacklisted) flags.push('Blacklisted');
      if (!gstinStatus.toUpperCase().includes('ACTIVE')) flags.push(`GSTIN ${gstinStatus}`);
      if (v.shared_director || v.shared_ip_address) flags.push('Collusion Alert');
      if (shellScore >= 75) flags.push(`Shell Risk: ${shellScore}`);

      if (v.shared_ip_address) sharedIPs.add(v.shared_ip_address);
      if (v.shared_director) sharedDirs.add(v.shared_director);

      return {
        key: v.vendor_id || i,
        vendorId: v.vendor_id,
        name: v.vendor_name || 'Unknown Vendor',
        category: v.vendor_category || 'Uncategorized',
        gstOk: gstinStatus.toUpperCase().includes('ACTIVE'),
        gstinStatus: gstinStatus,
        score: score,
        shellScore: shellScore,
        flags: flags,
        isDanger: isHighRisk,
        rawData: v
      };
    }).sort((a, b) => b.score - a.score);

    const avgScore = vendors.length ? Math.round(totalScore / vendors.length) : 0;
    clusters = sharedIPs.size + sharedDirs.size;

    const filteredData = tableData.filter(r => {
      if (search && !String(r.name).toLowerCase().includes(search.toLowerCase()) && !String(r.vendorId).toLowerCase().includes(search.toLowerCase())) return false;
      if (filter === 'high' && !r.isDanger) return false;
      if (filter === 'medium' && (r.score > 70 || r.score <= 40)) return false;
      if (filter === 'low' && r.score > 40) return false;
      return true;
    });

    const columns = [
      {
        title: 'Vendor Details', key: 'name',
        render: (_, record) => {
          const initial = record.name.charAt(0).toUpperCase();
          const bg = record.isDanger ? '#FFEBEE' : record.score > 40 ? '#FFF8E1' : '#E8F5E9';
          const txt = record.isDanger ? '#D32F2F' : record.score > 40 ? '#F9A825' : '#2E7D32';
          return (
            <div style={{display:'flex', alignItems:'center', gap:'12px'}}>
              <div style={{width:'36px', height:'36px', borderRadius:'8px', backgroundColor: bg, color: txt, display:'flex', alignItems:'center', justifyContent:'center', fontWeight:'bold', fontSize:'16px'}}>{initial}</div>
              <div>
                <div style={{fontWeight:'bold', color:'#0F0B0B'}}>{record.name}</div>
                <div style={{fontSize:'10px', color:'#75787B', textTransform:'uppercase', marginTop:'2px'}}>{record.category} | {record.vendorId}</div>
              </div>
            </div>
          );
        }
      },
      {
        title: 'GSTIN Status', key: 'gst',
        render: (_, record) => {
          const ok = record.gstOk;
          const bg = ok ? '#E8F5E9' : '#FFEBEE';
          const txt = ok ? '#2E7D32' : '#C62828';
          return <span style={{padding:'4px 8px', borderRadius:'4px', backgroundColor:bg, color:txt, fontSize:'11px', fontWeight:'bold'}}>{ok ? '● ACTIVE' : `● ${record.gstinStatus.toUpperCase()}`}</span>;
        }
      },
      {
        title: 'Avg Risk Score', key: 'score',
        render: (_, record) => <ScoreBar score={record.score} />
      },
      {
        title: 'Anomalies & Collusion', key: 'flags',
        render: (_, record) => {
          if (record.flags.length === 0) return <span style={{color:'#D0D0CE', fontStyle:'italic', fontSize:'12px'}}>— Clear —</span>;
          return (
            <div style={{display:'flex', flexWrap:'wrap', gap:'6px'}}>
              {record.flags.map(f => <span key={f} style={{padding:'2px 6px', border:'1px solid #D0D0CE', borderRadius:'4px', fontSize:'10px', fontWeight:'bold', color:'#75787B', backgroundColor:'#FBFBFB'}}>{f}</span>)}
            </div>
          );
        }
      },
      {
        title: 'Actions', key: 'action', align: 'right',
        render: (_, record) => (
          <button
            style={{backgroundColor:'#fff', border:'1px solid #D0D0CE', padding:'6px 12px', borderRadius:'6px', cursor:'pointer', fontWeight:'bold', fontSize:'12px', display:'inline-flex', alignItems:'center', gap:'6px', color:'#0F0B0B', boxShadow:'0 1px 2px rgba(0,0,0,0.05)', transition: 'all 0.2s'}}
            onClick={(e) => this.sendVendorEmail(record, e)}
            onMouseOver={(e) => { e.currentTarget.style.backgroundColor = '#86BC25'; e.currentTarget.style.color = '#fff'; e.currentTarget.style.borderColor = '#86BC25'; }}
            onMouseOut={(e) => { e.currentTarget.style.backgroundColor = '#fff'; e.currentTarget.style.color = '#0F0B0B'; e.currentTarget.style.borderColor = '#D0D0CE'; }}
          >
            <i data-lucide="mail" style={{width:'14px', height:'14px'}}></i> Contact
          </button>
        )
      }
    ];

    return (
      <div style={{padding:'24px', backgroundColor:'#FBFBFB', minHeight:'100vh', fontFamily:'sans-serif'}}>
        <div style={{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:'24px'}}>
          <div>
            <div style={{fontSize:'12px', color:'#75787B', marginBottom:'4px'}}>Risk &amp; Compliance <span>›</span> Vendor Intelligence</div>
            <h2 style={{margin:0, fontSize:'24px', fontWeight:'bold', color:'#0F0B0B'}}><GreenDot /> Vendor Intelligence</h2>
            <p style={{margin:'4px 0 0', fontSize:'14px', color:'#75787B'}}>Real-time analysis of vendor risk, collusion patterns, and shell company indicators</p>
          </div>
          <div style={{display:'flex', gap:'8px'}}>
            <button onClick={() => window.print()} style={{padding:'8px 16px', backgroundColor:'#fff', border:'1px solid #D0D0CE', borderRadius:'8px', fontSize:'14px', fontWeight:'bold', cursor:'pointer'}}>⬇ Export Report</button>
          </div>
        </div>

        <div style={{display:'grid', gridTemplateColumns:'repeat(4, 1fr)', gap:'16px', marginBottom:'24px'}}>
          <KpiCard label="Total Vendors" value={vendors.length} trend="Across all units" color="#00A3E0" />
          <KpiCard label="High Risk" value={highRiskCount} trend={`${Math.round(highRiskCount / vendors.length * 100) || 0}% of portfolio`} accent="warning" color="#F9A825" valueColor="#F9A825" />
          <KpiCard label="Blacklisted" value={blacklistedCount} trend="Immediate review" accent="danger" color="#D32F2F" valueColor="#D32F2F" />
          <KpiCard label="Avg Risk Score" value={`${avgScore} / 100`} trend={avgScore > 50 ? 'Elevated' : 'Within tolerance'} color="#86BC25" />
        </div>

        <div style={{display:'grid', gridTemplateColumns:'2fr 1fr', gap:'16px', marginBottom:'24px'}}>
          <Card title="Vendor Network Graph" extra={<span style={{fontSize:'12px', color:'#75787B', fontWeight:'bold', textTransform:'uppercase'}}>Collusion Detection</span>} bodyStyle={{padding:0}}>
            <NetworkGraph vendors={tableData} />
          </Card>
          <Card title="External Risk Metrics" extra={<span style={{fontSize:'12px', color:'#86BC25', fontWeight:'bold', backgroundColor:'#E8F5E9', padding:'2px 6px', borderRadius:'4px'}}>LIVE</span>}>
            <RiskMetrics validGst={validGst} suspendedGst={suspendedGst} clusters={clusters} total={vendors.length} />
          </Card>
        </div>

        <Card 
          title="Vendor Master List" 
          extra={
            <div style={{display:'flex', gap:'12px'}}>
              <input type="text" placeholder="Search vendor or ID..." value={search} onChange={e => this.setState({search: e.target.value})} style={{padding:'6px 12px', border:'1px solid #D0D0CE', borderRadius:'6px', fontSize:'13px', outline:'none'}} />
              <select value={filter} onChange={e => this.setState({filter: e.target.value})} style={{padding:'6px 12px', border:'1px solid #D0D0CE', borderRadius:'6px', fontSize:'13px', backgroundColor:'#fff', outline:'none'}}>
                <option value="all">All Severities</option>
                <option value="high">High Risk Only</option>
                <option value="medium">Medium Only</option>
                <option value="low">Low Risk Only</option>
              </select>
            </div>
          }
        >
          <div style={{overflowX:'auto'}}>
            <table style={{width:'100%', borderCollapse:'collapse', textAlign:'left', fontSize:'13px'}}>
              <thead>
                <tr style={{backgroundColor:'#F3F4F6', color:'#75787B', textTransform:'uppercase', fontSize:'11px'}}>
                  {columns.map(c => <th key={c.key} style={{padding:'12px 16px', borderBottom:'1px solid #D0D0CE', textAlign: c.align || 'left'}}>{c.title}</th>)}
                </tr>
              </thead>
              <tbody>
                {filteredData.length === 0 ? (
                  <tr><td colSpan={columns.length} style={{padding:'24px', textAlign:'center', color:'#75787B'}}>No vendors match your search.</td></tr>
                ) : filteredData.map(row => (
                  <tr key={row.key} style={{borderBottom:'1px solid #F3F4F6', transition:'background 0.2s'}} onMouseOver={e => e.currentTarget.style.backgroundColor='#F9FAFB'} onMouseOut={e => e.currentTarget.style.backgroundColor='transparent'}>
                    {columns.map(c => <td key={c.key} style={{padding:'12px 16px', textAlign: c.align || 'left'}}>{c.render(null, row)}</td>)}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>

        <Chatbot />
      </div>
    );
  }
}

appsmith.onReady(function () {
  reactDom.render(<App />, document.getElementById("root"));
});

