import React from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm'
import reactDom from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm'
import * as d3 from 'https://cdn.jsdelivr.net/npm/d3@7/+esm'

const { useState, useEffect, useRef } = React;
const FLOWISE_API = 'https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/a70f8f8e-a621-47a6-a7c9-20dd347bf0e5';

// ─── Stateless presentational components ───
function GreenDot() { return <span className="green-dot" style={{display: 'inline-block', width:'10px', height:'10px', backgroundColor:'#86BC25', borderRadius:'50%', marginRight:'8px'}} />; }

function KpiCard(props) {
  return (
    <div className={`kpi-card kpi-${props.accent}`} style={{backgroundColor:'#fff', padding:'16px', borderRadius:'12px', border:'1px solid #D0D0CE', borderLeft:`4px solid ${props.color || '#86BC25'}`, boxShadow:'0 1px 2px rgba(0,0,0,0.05)'}}>
      <div className="kpi-body">
        <p className="kpi-label" style={{fontSize:'11px', fontWeight:'bold', color:'#75787B', textTransform:'uppercase', letterSpacing:'0.5px'}}>{props.label}</p>
        <p className="kpi-value" style={{fontSize:'24px', fontWeight:'900', marginTop:'4px', color: props.valueColor || '#0F0B0B'}}>{props.value}</p>
        {props.trend ? <p className="kpi-trend" style={{fontSize:'12px', color:'#75787B', marginTop:'4px'}}>{props.trend}</p> : null}
      </div>
    </div>
  );
}

function ScoreBar(props) {
  const score = props.score;
  const fillClass = score > 70 ? '#D32F2F' : score > 40 ? '#F9A825' : '#2E7D32';
  const label = score > 70 ? 'High' : score > 40 ? 'Med' : 'Low';
  const pillBg = score > 70 ? '#FFEBEE' : score > 40 ? '#FFF8E1' : '#E8F5E9';

  return (
    <div style={{display:'flex', alignItems:'center', gap:'8px'}}>
      <div style={{width:'60px', height:'6px', backgroundColor:'#F3F4F6', borderRadius:'3px', overflow:'hidden'}}>
        <div style={{ width: `${score}%`, backgroundColor: fillClass, height: '100%' }} />
      </div>
      <span style={{fontWeight:'bold', fontSize:'13px', color: fillClass}}>{score}</span>
      <span style={{fontSize:'10px', fontWeight:'bold', padding:'2px 6px', borderRadius:'4px', backgroundColor: pillBg, color: fillClass}}>{label}</span>
    </div>
  );
}

// ─── D3.js Dynamic Network Graph ───
function NetworkGraph({ vendors }) {
  const svgRef = useRef(null);

  useEffect(() => {
    if (!vendors || vendors.length === 0) return;

    const nodes = [];
    const links = [];
    const entityMap = new Map();

    vendors.forEach(v => {
      const dir = v.rawData?.shared_director;
      const ip = v.rawData?.shared_ip_address;

      if (dir || ip) {
        if (!entityMap.has(v.vendorId)) {
          entityMap.set(v.vendorId, { id: v.vendorId, label: v.name.split(' ')[0], full_name: v.name, type: 'vendor', risk: v.isDanger });
          nodes.push(entityMap.get(v.vendorId));
        }

        if (dir) {
          const dirId = `DIR_${dir.replace(/\s+/g, '')}`;
          if (!entityMap.has(dirId)) {
            entityMap.set(dirId, { id: dirId, label: 'DIR', full_name: `Director: ${dir}`, type: 'director' });
            nodes.push(entityMap.get(dirId));
          }
          links.push({ source: v.vendorId, target: dirId });
        }

        if (ip) {
          const ipId = `IP_${ip.replace(/\./g, '')}`;
          if (!entityMap.has(ipId)) {
            entityMap.set(ipId, { id: ipId, label: 'IP', full_name: `IP: ${ip}`, type: 'ip' });
            nodes.push(entityMap.get(ipId));
          }
          links.push({ source: v.vendorId, target: ipId });
        }
      }
    });

    if (nodes.length === 0) {
        d3.select(svgRef.current).selectAll("*").remove();
        return; 
    }

    const width = 600;
    const height = 240;
    const svg = d3.select(svgRef.current)
      .attr("viewBox", [0, 0, width, height])
      .style("width", "100%")
      .style("height", "100%");

    svg.selectAll("*").remove(); 

    const simulation = d3.forceSimulation(nodes)
      .force("link", d3.forceLink(links).id(d => d.id).distance(100))
      .force("charge", d3.forceManyBody().strength(-400))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collide", d3.forceCollide().radius(35));

    const link = svg.append("g")
      .attr("stroke", "#D32F2F")
      .attr("stroke-opacity", 0.6)
      .attr("stroke-width", 2)
      .attr("stroke-dasharray", "5,5")
      .selectAll("line")
      .data(links)
      .join("line");

    const node = svg.append("g")
      .selectAll("g")
      .data(nodes)
      .join("g")
      .call(drag(simulation));

    node.append("circle")
      .attr("r", d => d.type === 'vendor' ? 22 : 18)
      .attr("fill", d => d.type === 'vendor' ? '#fff' : (d.type === 'director' ? '#0F0B0B' : '#75787B'))
      .attr("stroke", d => d.type === 'vendor' ? (d.risk ? '#D32F2F' : '#86BC25') : '#F9A825')
      .attr("stroke-width", 3)
      .style("cursor", "pointer");

    node.append("text")
      .text(d => d.type === 'vendor' ? d.label.substring(0,6) : d.label)
      .attr("text-anchor", "middle")
      .attr("dy", 4)
      .attr("fill", d => d.type === 'vendor' ? '#0F0B0B' : '#fff')
      .attr("font-size", d => d.type === 'vendor' ? "11px" : "10px")
      .attr("font-weight", "bold")
      .style("pointer-events", "none");

    node.append("title").text(d => d.full_name);

    simulation.on("tick", () => {
      link.attr("x1", d => Math.max(22, Math.min(width - 22, d.source.x)))
          .attr("y1", d => Math.max(22, Math.min(height - 22, d.source.y)))
          .attr("x2", d => Math.max(18, Math.min(width - 18, d.target.x)))
          .attr("y2", d => Math.max(18, Math.min(height - 18, d.target.y)));

      node.attr("transform", d => `translate(${Math.max(22, Math.min(width - 22, d.x))},${Math.max(22, Math.min(height - 22, d.y))})`);
    });

    function drag(simulation) {
      function dragstarted(event) {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        event.subject.fx = event.subject.x;
        event.subject.fy = event.subject.y;
      }
      function dragged(event) {
        event.subject.fx = event.x;
        event.subject.fy = event.y;
      }
      function dragended(event) {
        if (!event.active) simulation.alphaTarget(0);
        event.subject.fx = null;
        event.subject.fy = null;
      }
      return d3.drag()
        .on("start", dragstarted)
        .on("drag", dragged)
        .on("end", dragended);
    }

    return () => simulation.stop(); 
  }, [vendors]);

  const hasCollusion = vendors.some(v => v.rawData?.shared_director || v.rawData?.shared_ip_address);

  return (
    <div className="network-canvas" style={{position:'relative', backgroundColor:'#0F0B0B', padding:'20px', borderRadius:'0 0 12px 12px', height:'260px', overflow:'hidden'}}>
      {!hasCollusion ? (
        <div style={{display:'flex', height:'100%', alignItems:'center', justifyContent:'center', color:'#86BC25', flexDirection:'column'}}>
            <i data-lucide="shield-check" style={{width:'40px', height:'40px', marginBottom:'8px'}}></i>
            <p style={{fontWeight:'bold', fontSize:'14px'}}>No Collusion Networks Detected</p>
            <p style={{fontSize:'12px', color:'#75787B'}}>Vendor ecosystem is currently clean.</p>
        </div>
      ) : (
        <>
            <svg ref={svgRef} style={{width:'100%', height:'100%'}}></svg>
            <div style={{position:'absolute', bottom:'20px', left:'20px', backgroundColor:'rgba(211,47,47,0.1)', border:'1px solid #D32F2F', padding:'12px', borderRadius:'8px', color:'#fff', maxWidth:'80%', pointerEvents:'none'}}>
              <span style={{fontSize:'10px', fontWeight:'bold', color:'#FFCDD2', display:'block', marginBottom:'4px'}}>⚠ COLLUSION ALERT</span>
              <p style={{fontSize:'12px', margin:0}}>Network indicates shared infrastructure or leadership among vendors.</p>
            </div>
            <div style={{position:'absolute', top:'20px', right:'20px', display:'flex', gap:'12px', fontSize:'10px', color:'#D0D0CE', fontWeight:'bold'}}>
                <span style={{display:'flex', alignItems:'center', gap:'4px'}}><div style={{width:'10px', height:'10px', borderRadius:'50%', backgroundColor:'#fff', border:'2px solid #86BC25'}}/> Vendor</span>
                <span style={{display:'flex', alignItems:'center', gap:'4px'}}><div style={{width:'10px', height:'10px', borderRadius:'50%', backgroundColor:'#0F0B0B', border:'2px solid #F9A825'}}/> Director</span>
                <span style={{display:'flex', alignItems:'center', gap:'4px'}}><div style={{width:'10px', height:'10px', borderRadius:'50%', backgroundColor:'#75787B', border:'2px solid #F9A825'}}/> IP Addr</span>
            </div>
        </>
      )}
    </div>
  );
}

