// ─── Chatbot Component (React Hooks) ───
function Chatbot() {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [history, setHistory] = useState([
    { sender: 'bot', text: "<strong>Vendor Intelligence AI</strong><br>I can analyze specific vendor profiles, summarize collusion risks, or draft compliance emails. What do you need?" }
  ]);
  const [loading, setLoading] = useState(false);
  const endRef = useRef(null);

  const suggestions = ["Analyze shell company risk", "Draft vendor suspension notice", "Review recent blacklists"];

  useEffect(() => {
    if (endRef.current) endRef.current.scrollIntoView({ behavior: 'smooth' });
    if (isOpen) setTimeout(() => { if (typeof lucide !== 'undefined') lucide.createIcons(); }, 50);
  }, [history, isOpen]);

  const parseMarkdown = (text) => {
      if (!text) return "";
      return text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                 .replace(/`(.*?)`/g, '<code style="background:#F3F4F6; padding:2px 4px; border-radius:4px; color:#D32F2F; font-family:monospace; font-size:12px;">$1</code>')
                 .replace(/\n/g, '<br>');
  };

  const handleSend = async (textToSend) => {
    const text = textToSend || input;
    if (!text.trim()) return;

    setHistory(prev => [...prev, { sender: 'user', text: `<b>You:</b> ${text}` }]);
    setInput('');
    setLoading(true);

    try {
        const response = await fetch(FLOWISE_API, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ question: text + "\n[System Note: Context is Vendor Intelligence and Risk Management]" }) 
        });
        const data = await response.json();
        let reply = data.text || data.answer || JSON.stringify(data);
        setHistory(prev => [...prev, { sender: 'bot', text: parseMarkdown(reply) }]);
    } catch (e) {
        setHistory(prev => [...prev, { sender: 'bot', text: `<span style="color:#D32F2F; font-size:12px;"><b>Error:</b> AI connection timeout.</span>` }]);
    }
    setLoading(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end gap-4" style={{position: 'fixed', bottom: '24px', right: '24px', zIndex: 50, display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '16px'}}>
      {isOpen && (
        <div style={{width:'320px', backgroundColor:'#fff', border:'1px solid #D0D0CE', borderRadius:'16px', overflow:'hidden', boxShadow:'0 10px 25px rgba(0,0,0,0.1)', display:'flex', flexDirection:'column'}}>
          <div style={{backgroundColor:'#0F0B0B', color:'#fff', padding:'16px', display:'flex', justifyContent:'space-between', alignItems:'center'}}>
            <div style={{display:'flex', alignItems:'center', gap:'8px'}}>
              <i data-lucide="bot" style={{width:'20px', height:'20px', color:'#86BC25'}}></i>
              <h3 style={{fontWeight:'bold', margin:0, fontSize:'14px'}}>AuditIQ Assistant</h3>
            </div>
            <button onClick={() => setIsOpen(false)} style={{background:'none', border:'none', color:'#D0D0CE', cursor:'pointer'}}><i data-lucide="x" style={{width:'20px', height:'20px'}}></i></button>
          </div>
          <div style={{height:'350px', display:'flex', flexDirection:'column'}}>
            <div style={{flex:1, overflowY:'auto', padding:'16px', backgroundColor:'#FBFBFB', display:'flex', flexDirection:'column', gap:'12px'}}>
              {history.map((msg, i) => (
                <div key={i} style={{
                    maxWidth:'85%', padding:'12px', borderRadius:'8px', fontSize:'13px', lineHeight:'1.5',
                    alignSelf: msg.sender === 'user' ? 'flex-end' : 'flex-start',
                    backgroundColor: msg.sender === 'user' ? '#86BC25' : '#fff',
                    color: msg.sender === 'user' ? '#fff' : '#0F0B0B',
                    border: msg.sender === 'bot' ? '1px solid #D0D0CE' : 'none',
                    borderTopRightRadius: msg.sender === 'user' ? 0 : '8px',
                    borderTopLeftRadius: msg.sender === 'bot' ? 0 : '8px'
                }} dangerouslySetInnerHTML={{__html: msg.text}} />
              ))}
              {loading && <div style={{alignSelf:'flex-start', padding:'12px', backgroundColor:'#fff', border:'1px solid #D0D0CE', borderRadius:'8px', borderTopLeftRadius:0, fontSize:'13px', color:'#75787B', fontStyle:'italic'}}>Thinking...</div>}
              <div ref={endRef} />
            </div>
            {history.length === 1 && (
              <div style={{padding:'0 16px 12px', backgroundColor:'#FBFBFB', display:'flex', flexWrap:'wrap', gap:'8px'}}>
                {suggestions.map(s => (
                  <button key={s} onClick={() => handleSend(s)} style={{padding:'4px 12px', backgroundColor:'#fff', border:'1px solid #86BC25', color:'#86BC25', borderRadius:'999px', fontSize:'11px', fontWeight:'bold', cursor:'pointer'}}>{s}</button>
                ))}
              </div>
            )}
            <div style={{padding:'12px', backgroundColor:'#fff', borderTop:'1px solid #D0D0CE'}}>
              <input 
                type="text" 
                value={input} 
                onChange={e => setInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="Ask AI..." 
                style={{width:'100%', padding:'8px 12px', border:'1px solid #D0D0CE', borderRadius:'8px', fontSize:'13px', outline:'none', boxSizing:'border-box'}} 
              />
            </div>
          </div>
        </div>
      )}
      <button onClick={() => setIsOpen(!isOpen)} style={{width:'56px', height:'56px', backgroundColor:'#86BC25', color:'#fff', borderRadius:'50%', border:'none', boxShadow:'0 4px 12px rgba(134,188,37,0.4)', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center'}}>
        <i data-lucide="message-square" style={{width:'24px', height:'24px'}}></i>
      </button>
    </div>
  );
}

// ─── Main App as Class Component ───
class App extends React.Component {
  constructor(props) {
    super(props);
    this.state = { search: '', filter: 'all' };
  }

  componentDidMount() {
    setTimeout(() => { if (typeof lucide !== 'undefined') lucide.createIcons(); }, 100);
  }

  componentDidUpdate() {
    setTimeout(() => { if (typeof lucide !== 'undefined') lucide.createIcons(); }, 50);
  }

  sendVendorEmail = async (record, event) => {
    const btn = event.currentTarget;
    const originalHTML = btn.innerHTML;
    const originalPointerEvents = btn.style.pointerEvents;

    // Set Loading State
    btn.innerHTML = `Sending...`;
    btn.disabled = true;
    btn.style.pointerEvents = 'none'; // Prevent hover overriding states
    btn.style.opacity = "0.7";

    const issue = record.flags.length > 0 ? record.flags.join(", ") : "Routine Compliance Check";

    const payload = {
      question: JSON.stringify({
        intent: "vendor_outreach",
        vendor: record.name,
        issue: issue,
        recipient: "rimdaas30@gmail.com"
      })
    };

    try {
      const response = await fetch("https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/7d82d3ee-ddfd-46ee-9211-b1228072f3c9", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      const result = await response.json();

      // UI Success State
      btn.textContent = "Sent ✓";
      btn.style.backgroundColor = "#2e7d32"; // Success green
      btn.style.color = "#fff";
      btn.style.borderColor = "#2e7d32";
      btn.style.opacity = "1";
    } catch (error) {
      console.error("Outreach API Error:", error);
      // UI Error State
      btn.textContent = "Failed ✕";
      btn.style.backgroundColor = "#d32f2f"; // Error red
      btn.style.color = "#fff";
      btn.style.borderColor = "#d32f2f";
      btn.style.opacity = "1";
    }

    // Reset button after 3 seconds
    setTimeout(() => {
      btn.innerHTML = originalHTML;
      btn.disabled = false;
      btn.style.pointerEvents = originalPointerEvents;
      btn.style.backgroundColor = "#fff";
      btn.style.color = "#0F0B0B";
      btn.style.borderColor = "#D0D0CE";
      if (typeof lucide !== 'undefined') lucide.createIcons({root: btn});
    }, 3000);
  };

  render() {
    const { search, filter } = this.state;
    const rawData = appsmith.model;

    let vendors = [];
    if (Array.isArray(rawData)) vendors = rawData;
    else if (rawData && Array.isArray(rawData.vendorData)) vendors = rawData.vendorData;
    else if (rawData && typeof rawData === 'object') vendors = Object.values(rawData);

    if (!vendors || vendors.length === 0) {
      return (
        <div style={{padding:'40px', textAlign:'center', color:'#75787B'}}>
          <div style={{fontSize:'40px', marginBottom:'16px'}}>📊</div>
          <h3 style={{color:'#0F0B0B'}}>No vendor data loaded</h3>
          <p>Configure the fetch_vendor_intel API in Appsmith to begin analysis.</p>
        </div>
      );
    }

    let validGst = 0, suspendedGst = 0, blacklistedCount = 0, highRiskCount = 0, totalScore = 0;
    let clusters = 0;
    const sharedIPs = new Set();
    const sharedDirs = new Set();

    // Dynamically Map Real DB Fields
    const tableData = vendors.map((v, i) => {
      const score = parseFloat(v.avg_risk_score) || 0;
      const shellScore = parseInt(v.shell_risk_score) || 0;
      const gstinStatus = v.gstin_status || 'Unknown';
      const isBlacklisted = v.blacklisted === true || v.blacklisted === 't';
      const isHighRisk = score >= 70 || isBlacklisted;

      if (gstinStatus.toUpperCase().includes('ACTIVE')) validGst++; else suspendedGst++;
      if (isBlacklisted) blacklistedCount++;
      if (isHighRisk) highRiskCount++;
      totalScore += score;

      const flags = [];
      if (isBlacklisted) flags.push('Blacklisted');
      if (!gstinStatus.toUpperCase().includes('ACTIVE')) flags.push(`GSTIN ${gstinStatus}`);
      if (v.shared_director || v.shared_ip_address) flags.push('Collusion Alert');
      if (shellScore >= 75) flags.push(`Shell Risk: ${shellScore}`);

      if (v.shared_ip_address) sharedIPs.add(v.shared_ip_address);
      if (v.shared_director) sharedDirs.add(v.shared_director);

      return {
        key: v.vendor_id || i,
        vendorId: v.vendor_id,
        name: v.vendor_name || 'Unknown Vendor',
        category: v.vendor_category || 'Uncategorized',
        gstOk: gstinStatus.toUpperCase().includes('ACTIVE'),
        gstinStatus: gstinStatus,
        score: score,
        shellScore: shellScore,
        flags: flags,
        isDanger: isHighRisk,
        rawData: v
      };
    }).sort((a, b) => b.score - a.score);

    const avgScore = vendors.length ? Math.round(totalScore / vendors.length) : 0;
    clusters = sharedIPs.size + sharedDirs.size;

    const filteredData = tableData.filter(r => {
      if (search && !String(r.name).toLowerCase().includes(search.toLowerCase()) && !String(r.vendorId).toLowerCase().includes(search.toLowerCase())) return false;
      if (filter === 'high' && !r.isDanger) return false;
      if (filter === 'medium' && (r.score > 70 || r.score <= 40)) return false;
      if (filter === 'low' && r.score > 40) return false;
      return true;
    });

    const columns = [
      {
        title: 'Vendor Details', key: 'name',
