              </div>
            </div>
          );
        }
      },
      {
        title: 'GSTIN Status', key: 'gst',
        render: (_, record) => {
          const ok = record.gstOk;
          const bg = ok ? '#E8F5E9' : '#FFEBEE';
          const txt = ok ? '#2E7D32' : '#C62828';
          return <span style={{padding:'4px 8px', borderRadius:'4px', backgroundColor:bg, color:txt, fontSize:'11px', fontWeight:'bold'}}>{ok ? '● ACTIVE' : `● ${record.gstinStatus.toUpperCase()}`}</span>;
        }
      },
      {
        title: 'Avg Risk Score', key: 'score',
        render: (_, record) => <ScoreBar score={record.score} />
      },
      {
        title: 'Anomalies & Collusion', key: 'flags',
        render: (_, record) => {
          if (record.flags.length === 0) return <span style={{color:'#D0D0CE', fontStyle:'italic', fontSize:'12px'}}>— Clear —</span>;
          return (
            <div style={{display:'flex', flexWrap:'wrap', gap:'6px'}}>
              {record.flags.map(f => <span key={f} style={{padding:'2px 6px', border:'1px solid #D0D0CE', borderRadius:'4px', fontSize:'10px', fontWeight:'bold', color:'#75787B', backgroundColor:'#FBFBFB'}}>{f}</span>)}
            </div>
          );
        }
      },
      {
        title: 'Actions', key: 'action', align: 'right',
        render: (_, record) => (
          <button
            style={{backgroundColor:'#fff', border:'1px solid #D0D0CE', padding:'6px 12px', borderRadius:'6px', cursor:'pointer', fontWeight:'bold', fontSize:'12px', display:'inline-flex', alignItems:'center', gap:'6px', color:'#0F0B0B', boxShadow:'0 1px 2px rgba(0,0,0,0.05)', transition: 'all 0.2s'}}
            onClick={(e) => this.sendVendorEmail(record, e)}
            onMouseOver={(e) => { e.currentTarget.style.backgroundColor = '#86BC25'; e.currentTarget.style.color = '#fff'; e.currentTarget.style.borderColor = '#86BC25'; }}
            onMouseOut={(e) => { e.currentTarget.style.backgroundColor = '#fff'; e.currentTarget.style.color = '#0F0B0B'; e.currentTarget.style.borderColor = '#D0D0CE'; }}
          >
            <i data-lucide="mail" style={{width:'14px', height:'14px'}}></i> Contact
          </button>
        )
      }
    ];

    return (
      <div style={{padding:'24px', backgroundColor:'#FBFBFB', minHeight:'100vh', fontFamily:'sans-serif'}}>
        <div style={{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:'24px'}}>
          <div>
            <div style={{fontSize:'12px', color:'#75787B', marginBottom:'4px'}}>Risk &amp; Compliance <span>›</span> Vendor Intelligence</div>
            <h2 style={{margin:0, fontSize:'24px', fontWeight:'bold', color:'#0F0B0B'}}><GreenDot /> Vendor Intelligence</h2>
            <p style={{margin:'4px 0 0', fontSize:'14px', color:'#75787B'}}>Real-time analysis of vendor risk, collusion patterns, and shell company indicators</p>
          </div>
          <div style={{display:'flex', gap:'8px'}}>
            <button onClick={() => window.print()} style={{padding:'8px 16px', backgroundColor:'#fff', border:'1px solid #D0D0CE', borderRadius:'8px', fontSize:'14px', fontWeight:'bold', cursor:'pointer'}}>⬇ Export Report</button>
          </div>
        </div>

        <div style={{display:'grid', gridTemplateColumns:'repeat(4, 1fr)', gap:'16px', marginBottom:'24px'}}>
          <KpiCard label="Total Vendors" value={vendors.length} trend="Across all units" color="#00A3E0" />
          <KpiCard label="High Risk" value={highRiskCount} trend={`${Math.round(highRiskCount / vendors.length * 100) || 0}% of portfolio`} accent="warning" color="#F9A825" valueColor="#F9A825" />
          <KpiCard label="Blacklisted" value={blacklistedCount} trend="Immediate review" accent="danger" color="#D32F2F" valueColor="#D32F2F" />
          <KpiCard label="Avg Risk Score" value={`${avgScore} / 100`} trend={avgScore > 50 ? 'Elevated' : 'Within tolerance'} color="#86BC25" />
        </div>

        <div style={{display:'grid', gridTemplateColumns:'2fr 1fr', gap:'16px', marginBottom:'24px'}}>
          <Card title="Vendor Network Graph" extra={<span style={{fontSize:'12px', color:'#75787B', fontWeight:'bold', textTransform:'uppercase'}}>Collusion Detection</span>} bodyStyle={{padding:0}}>
            <NetworkGraph vendors={tableData} />
          </Card>
          <Card title="External Risk Metrics" extra={<span style={{fontSize:'12px', color:'#86BC25', fontWeight:'bold', backgroundColor:'#E8F5E9', padding:'2px 6px', borderRadius:'4px'}}>LIVE</span>}>
            <RiskMetrics validGst={validGst} suspendedGst={suspendedGst} clusters={clusters} total={vendors.length} />
          </Card>
        </div>

        <Card 
          title="Vendor Master List" 
          extra={
            <div style={{display:'flex', gap:'12px'}}>
              <input type="text" placeholder="Search vendor or ID..." value={search} onChange={e => this.setState({search: e.target.value})} style={{padding:'6px 12px', border:'1px solid #D0D0CE', borderRadius:'6px', fontSize:'13px', outline:'none'}} />
              <select value={filter} onChange={e => this.setState({filter: e.target.value})} style={{padding:'6px 12px', border:'1px solid #D0D0CE', borderRadius:'6px', fontSize:'13px', backgroundColor:'#fff', outline:'none'}}>
                <option value="all">All Severities</option>
                <option value="high">High Risk Only</option>
                <option value="medium">Medium Only</option>
                <option value="low">Low Risk Only</option>
              </select>
            </div>
          }
        >
          <div style={{overflowX:'auto'}}>
            <table style={{width:'100%', borderCollapse:'collapse', textAlign:'left', fontSize:'13px'}}>
              <thead>
                <tr style={{backgroundColor:'#F3F4F6', color:'#75787B', textTransform:'uppercase', fontSize:'11px'}}>
                  {columns.map(c => <th key={c.key} style={{padding:'12px 16px', borderBottom:'1px solid #D0D0CE', textAlign: c.align || 'left'}}>{c.title}</th>)}
                </tr>
              </thead>
              <tbody>
                {filteredData.length === 0 ? (
                  <tr><td colSpan={columns.length} style={{padding:'24px', textAlign:'center', color:'#75787B'}}>No vendors match your search.</td></tr>
                ) : filteredData.map(row => (
                  <tr key={row.key} style={{borderBottom:'1px solid #F3F4F6', transition:'background 0.2s'}} onMouseOver={e => e.currentTarget.style.backgroundColor='#F9FAFB'} onMouseOut={e => e.currentTarget.style.backgroundColor='transparent'}>
                    {columns.map(c => <td key={c.key} style={{padding:'12px 16px', textAlign: c.align || 'left'}}>{c.render(null, row)}</td>)}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>

        <Chatbot />
      </div>
    );
  }
}

appsmith.onReady(function () {
  reactDom.render(<App />, document.getElementById("root"));
});

