children.onDownloadClick:
{{
  (async () => {
    const reportName = Custom1.model.selectedReport;
    const format = Custom1.model.selectedFormat;

    try {
      await get_monthly_exceptions.run();
      const data = get_monthly_exceptions.data.rows;

      if (!data || data.length === 0) {
        showAlert('No data found to export.', 'warning');
        return;
      }

      if (format === 'CSV') {
        // Robust CSV Builder to handle complex JSON strings in columns
        const headers = Object.keys(data[0]).join(',');
        const csvRows = data.map(row => {
          return Object.values(row).map(value => {
            let str = value === null || value === undefined ? '' : String(value);
            // Escape double quotes and wrap in quotes if there's a comma or newline
            str = str.replace(/"/g, '""');
            if (str.search(/("|,|\n)/g) >= 0) {
              str = `"${str}"`;
            }
            return str;
          }).join(',');
        });

        const csvString = [headers, ...csvRows].join('\n');

        // Download the cleanly parsed string
        download(csvString, `${reportName.replace(/ /g, '_')}.csv`, 'text/csv');
        showAlert('CSV Download Complete', 'success');
      } 
      else if (format === 'PDF') {
        // We do nothing here! The query has refreshed the data, 
        // and the Default Model will automatically pass it to the widget.
      }
    } catch (err) {
      showAlert('Export failed: ' + err.message, 'error');
    }
  })()
}}

