import React, { useState, useEffect } from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm'
import reactDom from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm'
import { Download, Plus, FileText, CheckCircle, Clock, ShieldAlert, Search, Filter, X } from 'https://cdn.jsdelivr.net/npm/lucide-react@0.294.0/+esm'
import { jsPDF } from "https://cdn.jsdelivr.net/npm/jspdf@2.5.1/+esm"

// Hardcoded static templates so they never disappear
const DEFAULT_REPORTS = [
  { title: "Monthly Exception Summary", date: "May 2026", desc: "Aggregated view of all flagged items, overrides, and final statuses." },
  { title: "Vendor Risk Profile Export", date: "May 2026", desc: "Detailed breakdown of external risk metrics, GST statuses, and shell heuristics." },
  { title: "ISA 230 Traceability Log", date: "Q2 2026", desc: "Immutable chain of evidence for all transactions processed by the AI agents." },
  { title: "Proactive Tax Insights", date: "YTD 2026", desc: "Consolidated report on missed ITCs and structural procurement recommendations." },
  { title: "Collusion Network Export", date: "Last 30 Days", desc: "Graph data and identified clusters for offline regulatory review." }
];

function App() {
  const [reports] = useState(DEFAULT_REPORTS);
  const [history, setHistory] = useState([]);
  const [kpis, setKpis] = useState({ generated: "0", pending: "0", exported: "0", compliance: "0%" });
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [toast, setToast] = useState(null);

  // Bind Appsmith Model Data Safely
  useEffect(() => {
    const safeSetHistory = (historyData) => {
      if (!historyData) return;
      if (Array.isArray(historyData)) {
        setHistory(historyData);
      } else if (historyData.rows && Array.isArray(historyData.rows)) {
        setHistory(historyData.rows);
      } else {
        setHistory([]);
      }
    };

    if (typeof appsmith !== 'undefined') {
      appsmith.onModelChange((model) => {
        safeSetHistory(model.history);
        if (model.kpis) setKpis(model.kpis);
      });

      if (appsmith.model) {
        safeSetHistory(appsmith.model.history);
        if (appsmith.model.kpis) setKpis(appsmith.model.kpis);
      }
    }
  }, []);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleGenerate = () => {
    if (typeof appsmith !== 'undefined') {
      appsmith.triggerEvent("onGenerateClick");
    }
  };

  // --- PDF GENERATOR LOGIC ---
  const generatePDF = (data, title) => {
    try {
      const doc = new jsPDF();
      doc.setFontSize(18);
      doc.text("AuditIQ Forensic Report", 14, 20);

      doc.setFontSize(12);
      doc.setTextColor(100);
      doc.text(title, 14, 30);
      doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 38);

      doc.setLineWidth(0.5);
      doc.line(14, 42, 196, 42);

      let y = 52;
      doc.setFontSize(10);
      doc.setTextColor(0);

      // Map through the comprehensive database rows
      if (Array.isArray(data)) {
        data.forEach((row, i) => {
          if (y > 270) { doc.addPage(); y = 20; }

          const id = row.invoice_id || row.vendor_id || 'N/A';
          const name = row.vendor_name || 'N/A';
          const risk = row.risk_rating || row.risk_level || 'N/A';
          const score = row.risk_score || row.trigger_count || 0;

          doc.setFont(undefined, 'bold');
          doc.text(`${i + 1}. Reference: ${id} | Entity: ${name}`, 14, y);
          doc.setFont(undefined, 'normal');
          doc.setTextColor(100);
          doc.text(`Risk Metric: ${risk} | Score/Count: ${score}`, 14, y + 6);
          doc.setTextColor(0);

          y += 14;
        });
      }

      doc.save(`${title.replace(/\s+/g, '_')}.pdf`);
      showToast('PDF generated successfully!', 'success');
    } catch (err) {
      showToast('Error generating PDF', 'error');
      console.error(err);
    }
  };

  const handleDownload = (reportName, format) => {
    if (typeof appsmith !== 'undefined') {
      // 1. Tell Appsmith what we are downloading AND clear old data to prevent stale PDFs
      appsmith.updateModel({ 
        selectedReport: reportName, 
        selectedFormat: format,
        reportData: null 
      });

      appsmith.triggerEvent("onDownloadClick");
      showToast(`Initiating ${format} export...`, 'info');

      // 2. If it's a PDF, wait for the query to finish and the Default Model to update
      if (format === 'PDF') {
        let attempts = 0;
        const checkData = setInterval(() => {
          attempts++;
          const data = appsmith.model.reportData;

          // Once fresh data arrives from the DB query, generate the PDF
          if (data && Array.isArray(data) && data.length > 0) {
            generatePDF(data, reportName);
            clearInterval(checkData);

            // Clear it so it doesn't loop
            appsmith.updateModel({ reportData: null }); 
          } else if (attempts > 20) { // Timeout after 10 seconds
            clearInterval(checkData);
            showToast("Timed out waiting for database.", "error");
          }
        }, 500);
      }
    }
  };

  const filteredHistory = Array.isArray(history) ? history.filter(item => {
    if (!item || !item.name || !item.id) return false;
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          item.id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === "all" || (item.status && item.status.toLowerCase() === statusFilter.toLowerCase());
    return matchesSearch && matchesStatus;
  }) : [];

  return (
    <div className="app">
      {toast && (
        <div className={`toast fade-in ${toast.type}`}>
          <div className="toast-icon">
            {toast.type === 'success' ? <CheckCircle size={18} /> : <Clock size={18} />}
          </div>
          <span>{toast.msg}</span>
          <button className="toast-close" onClick={() => setToast(null)}><X size={14} /></button>
        </div>
      )}

      <div className="header fade-in">
        <div>
          <h2>Automated Audit Packs</h2>
          <p>Generate, track, and export forensic-grade audit documentation</p>
        </div>
        <button className="generate-btn" onClick={handleGenerate}>
          <Plus size={18} />
          Generate Custom Report
        </button>
      </div>

      <div className="kpi-row">
        {[
          { icon: <FileText size={24} />, label: "Reports Generated", value: kpis.generated, delay: "0s" },
          { icon: <Clock size={24} />, label: "Pending Review", value: kpis.pending, delay: "0.1s" },
          { icon: <Download size={24} />, label: "Exported This Month", value: kpis.exported, delay: "0.2s" },
          { icon: <ShieldAlert size={24} />, label: "Compliance Rate", value: kpis.compliance, delay: "0.3s" }
        ].map((kpi, i) => (
          <div key={i} className="kpi-card" style={{ animationDelay: kpi.delay }}>
            <div className="kpi-icon">{kpi.icon}</div>
            <div>
              <div className="kpi-value">{kpi.value || "0"}</div>
              <div className="kpi-label">{kpi.label}</div>
            </div>
          </div>
        ))}
      </div>

      <div className="reports-grid">
        {reports.map((r, i) => (
          <div key={i} className="report-card" style={{ animationDelay: `${0.2 + i * 0.1}s` }}>
            <div>
              <h3>{r.title}</h3>
              <span className="date">{r.date}</span>
              <p className="desc">{r.desc}</p>
            </div>
            <div className="card-actions">
              <button onClick={() => handleDownload(r.title, 'PDF')}><Download size={16} /> PDF</button>
              <button onClick={() => handleDownload(r.title, 'CSV')}><Download size={16} /> CSV</button>
            </div>
          </div>
        ))}
      </div>

      <div className="history-section" style={{ animationDelay: "0.6s" }}>
        <div className="history-header">
          <h3>Report Generation History</h3>
          <div className="history-controls">
            <div className="search-box">
              <Search size={16} />
              <input 
                type="text" 
                placeholder="Search ID or Name..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="filter-box">
              <Filter size={16} />
              <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
                <option value="all">All Statuses</option>
                <option value="success">Completed</option>
                <option value="pending">Pending</option>
                <option value="failed">Failed</option>
              </select>
            </div>
          </div>
        </div>

        <div className="table-wrapper">
          {filteredHistory.length > 0 ? (
            <table>
              <thead>
                <tr>
                  <th>Report ID</th>
                  <th>Report Name</th>
                  <th>Type</th>
                  <th>Generated Date</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredHistory.map((item, i) => (
                  <tr key={i}>
                    <td className="mono">{item.id}</td>
                    <td className="fw-600">{item.name}</td>
                    <td>{item.type}</td>
                    <td>{item.date}</td>
                    <td>
                      <span className={`status-badge status-${item.status?.toLowerCase() || 'pending'}`}>
                        {(item.status || 'Pending').charAt(0).toUpperCase() + (item.status || 'pending').slice(1)}
                      </span>
                    </td>
                    <td>
                      <button 
                        onClick={() => handleDownload(item.name, 'PDF')}
                        className="btn-text"
                      >
                        <Download size={14} /> Download
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <div className="empty-state fade-in">
              <FileText size={48} className="empty-icon" />
              <h4>No reports found</h4>
              <p>Try adjusting your search criteria or filters.</p>
              <button className="btn-outline" onClick={() => { setSearchTerm(''); setStatusFilter('all'); }}>
                Clear Filters
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

if (typeof appsmith !== 'undefined') {
  appsmith.onReady(() => {
    reactDom.render(<App />, document.getElementById("root"));
  });
} else {
  reactDom.render(<App />, document.getElementById("root"));
}

