// Initialize Lucide Icons
setTimeout(() => {
  if (typeof lucide !== 'undefined') {
    lucide.createIcons();
  }
}, 100);
let initialized = false;

// Function to update the active item visually
function setActiveItem(targetName) {
  const navItems = document.querySelectorAll('.nav-item');
  let found = false;
  navItems.forEach(item => {
    item.classList.remove('active');
    if (item.getAttribute('data-target') === targetName) {
      item.classList.add('active');
      found = true;
    }
  });

  // Fallback: if targeted page isn't found, keep Overview active
  if (!found && navItems.length > 0) {
    navItems[0].classList.add('active');
  }
}

// Attach click listeners to all nav items
function attachListeners() {
  const navItems = document.querySelectorAll('.nav-item');
  navItems.forEach(item => {
    // Prevent multiple bindings
    item.removeEventListener('click', navClickHandler);
    item.addEventListener('click', navClickHandler);
  });
}
function navClickHandler(e) {
  const targetPageName = e.currentTarget.getAttribute('data-target');

  // Visually update immediately for snappy UX
  setActiveItem(targetPageName);

  // Fire the navigation up to Appsmith
  if (typeof appsmith !== 'undefined') {
    appsmith.updateModel({
      destination: targetPageName
    });
    appsmith.triggerEvent('onNavigate');
  } else {
    console.log(`[Local Mode] Triggered navigation to: ${targetPageName}`);
  }
}

// --- Appsmith Integration ---
if (typeof appsmith !== 'undefined') {
  appsmith.onReady(() => {
    attachListeners();

    // Map initial state if passed down from Appsmith
    if (appsmith.model && appsmith.model.currentPage) {
      setActiveItem(appsmith.model.currentPage);
    }
    initialized = true;
  });
  appsmith.onModelChange(model => {
    // If the parent Appsmith app changes the page programmatically (e.g. back button),
    // we map it back to the sidebar so the highlight stays in sync.
    if (model && model.currentPage) {
      setActiveItem(model.currentPage);
    }
  });
} else {
  // Local testing initialization
  window.addEventListener('DOMContentLoaded', attachListeners);
}

